return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es_ES','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 19:40+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lengua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Enrutamiento multilingüe, SEO multilingüe completo (hreflang, Open Graph, Schema.org, sitemap), y herramientas de contenido AI para WordPress. Detección de idioma, enrutamiento de URL, traducción, generación de contenido y una capa SEO completa — sin necesidad de plugin complementario.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Traducir','Lingua Forge — Quick Translate'=>'Lengua Forge — Traducción rápida','Informative'=>'Informativo','Persuasive'=>'Persuasivo','Storytelling'=>'Narración','Technical'=>'Técnico','Conversational'=>'Conversacional','Permission denied.'=>'Permiso denegado.','Cannot determine target language from slug.'=>'No se puede determinar el idioma de destino a partir del slug.','Invalid post type.'=>'Tipo de publicación no válido.','Invalid or primary language.'=>'Idioma inválido o principal.','Template not found or not stored in the database.'=>'Plantilla no encontrada o no almacenada en la base de datos.','Template has no content.'=>'La plantilla no tiene contenido.','No internal links found to update.'=>'No se encontraron enlaces internos para actualizar.','%d link updated.'=>'%d enlace actualizado.' . "\0" . '%d enlaces actualizados.','No language-specific template parts found to map.'=>'No se encontraron partes de plantilla específicas del idioma para mapear.','No template part references needed updating.'=>'No se necesitan actualizar referencias de partes de plantilla.','%d part reference updated.'=>'Se actualizó la referencia de %d parte.' . "\0" . 'Se actualizaron %d referencias de partes.','Invalid language.'=>'Idioma no válido.','Template part not found or not stored in the database.'=>'Parte de plantilla no encontrada o no almacenada en la base de datos.','Template part has no content.'=>'La parte de la plantilla no tiene contenido.','No navigation references needed updating.'=>'No se necesitan actualizar referencias de navegación.','%d navigation reference updated.'=>'Se actualizó %d referencia de navegación.' . "\0" . 'Se actualizaron %d referencias de navegación.','No AI provider configured.'=>'No se ha configurado ningún proveedor de IA.','Missing pattern name or language.'=>'Falta el nombre del patrón o el idioma.','Pattern not found.'=>'Patrón no encontrado.','Pattern has no content to translate.'=>'El patrón no tiene contenido para traducir.','AI provider returned an empty response.'=>'El proveedor de IA devolvió una respuesta vacía.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patrón traducido y guardado. Copie el contenido en su publicación CPT mediante el inserto de patrones del editor de bloques o utilícelo como punto de partida para un bloque reutilizable.','%d template repaired.'=>'%d plantilla(s) reparada(s).' . "\0" . '%d plantillas reparadas.','All template metadata is already up to date.'=>'Todos los metadatos de las plantillas ya están actualizados.','Invalid template type.'=>'Tipo de plantilla no válido.','Template "%s" already exists.'=>'La plantilla "%s" ya existe.','Fix Links'=>'Corregir enlaces','Fix Parts'=>'Corregir partes','Re-create'=>'Recrear','"%s" recreated.'=>'"%s" recreado.','"%s" created.'=>'"%s" creado.','Invalid template part.'=>'Parte de plantilla no válida.','Template part "%s" already exists.'=>'La parte de plantilla "%s" ya existe.','Fix Nav'=>'Corregir navegación','"%1$s" recreated. %2$d template updated.'=>'"%1$s" recreado. %2$d plantilla actualizada.' . "\0" . '"%1$s" recreado. %2$d plantillas actualizadas.','"%1$s" created. %2$d template updated.'=>'"%1$s" creado. %2$d plantilla actualizada.' . "\0" . '"%1$s" creado. %2$d plantillas actualizadas.','Page'=>'Página','Single'=>'Individual','Search'=>'Buscar','Search Results'=>'Resultados de búsqueda','Archive'=>'Archivo','Front Page'=>'Página principal','Blog Home'=>'Inicio del blog','Single: %s'=>'Individual: %s','Single %s'=>'Individual %s','Archive: %s'=>'Archivo: %s','%s Archive'=>'Archivo de %s','No source content found to translate.'=>'No se encontró contenido fuente para traducir.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traducido. Revisa en el Editor del Sitio — los enlaces internos, URLs de navegación y slugs de plantillas no se actualizan automáticamente.','Navigation not found.'=>'Navegación no encontrada.','Navigation has no content to translate.'=>'La navegación no tiene contenido para traducir.','"%1$s %2$s" saved.'=>'"%1$s %2$s" guardado.','SEO Analysis'=>'Análisis SEO','Profile'=>'Perfil','Details ↗'=>'Detalles ↗','/ 100'=>'/ 100','Overall SEO score'=>'Puntuación general de SEO','Metric'=>'Métrica','Finding'=>'Encontrando','Title'=>'Título','Meta description'=>'Meta descripción','Word count'=>'Recuento de palabras','Reading time'=>'Tiempo de lectura','Headings'=>'Encabezados','Images'=>'Imágenes','Links'=>'Enlaces','AI Recommendations'=>'Recomendaciones de IA','Run AI Analysis'=>'Ejecutar análisis de IA','Analyzing…'=>'Analizando…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configura un proveedor de IA en Configuración → Claves API para habilitar recomendaciones impulsadas por IA.','AI analysis failed. Please try again.'=>'Fallo en el análisis de IA. Por favor, intenta de nuevo.','Suggested title'=>'Título sugerido','Suggested meta description'=>'Meta descripción sugerida','Loaded from cache.'=>'Cargado desde la caché.','↺ Refresh AI Analysis'=>'↺ Actualizar análisis de IA','Analyse…'=>'Analizar…','Analysis request failed. Please try again.'=>'Fallo en la solicitud de análisis. Por favor, intenta de nuevo.','No translation found — analyzed the source language version.'=>'No se encontró ninguna traducción — se analizó la versión en idioma fuente.','Translate page…'=>'Traducir página…','Generate content…'=>'Generar contenido…','AI Behaviour Preset'=>'Preajuste de comportamiento de IA','Custom'=>'Personalizado','Global default (%s)'=>'Predeterminado global (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobrescribe el preajuste de IA para Traducción y Generación de contenido en esta página. Las instrucciones personalizadas a nivel de sitio (Configuración → Comportamiento) siempre se añaden a cada solicitud independientemente de esta selección.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobrescribe el preajuste de IA para Traducción y Generación de contenido en esta página. Todas las demás funciones siempre usan el preajuste global.','Close'=>'Cerrar','Translate missing'=>'Falta traducción','From'=>'De','Retranslate'=>'Retraducir','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Retraduce cada otra versión de idioma de esta entrada. Crea las que falten y sobrescribe las que ya existan — incluso el idioma principal, si esta entrada es una traducción.','Sync'=>'Sincronizar','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Asigna la plantilla específica de idioma correcta a todas las traducciones existentes de esta entrada. Sin llamadas de IA ni cambios de contenido — gratuito y seguro para ejecutar en cualquier momento.','Template Sync — reassign templates for every translation'=>'Sincronización de plantillas — reasignar plantillas para todas las traducciones','TS'=>'SP','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Última puntuación SEO basada en reglas. Ejecute análisis en Configuración → SEO → Análisis para actualizar.','Translating…'=>'Traduciendo…','Retranslating…'=>'Retraduciendo…','Syncing…'=>'Sincronizando…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Esto retraduce todas las demás versiones de idioma de esta entrada a partir de esta — creando las que falten y sobrescribiendo las que ya existan (incluyendo el idioma principal, si esta entrada es una traducción). Esto no se puede deshacer. ¿Continuar?','Syncing templates…'=>'Sincronizando plantillas…','✓ Done'=>'✓ Hecho','Error'=>'Error','Navigation posts are translated via the Router tab, not this button.'=>'Las publicaciones de navegación se traducen a través de la pestaña Router, no con este botón.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Crear traducciones para el tipo de publicación "%s" requiere una integración activa. Asegúrate de que la integración requerida esté instalada y activa.','No %s version found in this translation group.'=>'No se encontró ninguna versión de %s en este grupo de traducciones.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'La sincronización desde un producto WooCommerce de idioma secundario está deshabilitada por defecto, ya que sobrescribiría el producto principal. Actívalo en Configuración → Comportamiento → WooCommerce si deseas que una traducción pueda convertirse en el nuevo contenido fuente.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'La sincronización desde una entrada de idioma secundario está deshabilitada por defecto, ya que sobrescribiría la entrada principal. Actívalo en Configuración → Comportamiento → Sincronizar si deseas que una traducción pueda convertirse en el nuevo contenido fuente.','Skipped — you do not have permission to edit the existing translation.'=>'Omitido — no tienes permiso para editar la traducción existente.','Creating translations for post type "%s" requires an active integration.'=>'Crear traducciones para el tipo de entrada "%s" requiere una integración activa.','Template Sync can only be run from the primary/source-language post.'=>'La sincronización de plantillas solo se puede ejecutar desde la entrada del idioma principal/fuente.','Skipped — you do not have permission to edit this translation.'=>'Omitido — no tienes permiso para editar esta traducción.','Translation Caching'=>'Caché de traducción','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge usa dos capas de caché independientes para evitar llamadas redundantes a la API de IA. Use las pestañas a continuación para inspeccionar y gestionar cada una.','API Response Cache'=>'Caché de respuestas API','Translation Memory'=>'Memoria de traducción','(disabled)'=>'(desactivado)','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Caché por publicación para traducciones generadas por IA, descripciones meta, extractos y contenido. Las entradas se invalidan automáticamente cuando el contenido o el proveedor/modelo de IA cambian.','Enable API response caching'=>'Habilitar caché de respuestas API','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'La caché de respuestas de la API almacena el resultado en bruto de cada solicitud de IA — traducción, descripción meta, extracto y generación de contenido — identificada por un hash de las entradas (contenido, par de idiomas, proveedor, modelo). Desactívala durante la afinación de prompts o cuando necesites que cada solicitud llegue al proveedor de IA. La desactivación no elimina las entradas en caché — volver a activarla las restaura.','Save'=>'Guardar','Cached API responses'=>'Respuestas API en caché','API calls saved by cache'=>'Llamadas API guardadas por caché','(avg %.1f hits/entry)'=>'(promedio %.1f aciertos/entrada)','Oldest cached response'=>'Respuesta en caché más antigua','Most recent cached response'=>'Respuesta en caché más reciente','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'¿Borrar todos los resultados en caché de IA? Las solicitudes futuras activarán llamadas API nuevas hasta que se reconstruya la caché.','Clear API Response Cache'=>'Borrar caché de respuestas API','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Caché de traducción a nivel de bloque compartida entre publicaciones. Cuando está habilitado, bloques idénticos (mismo marcado, par de idiomas y glosario) se sirven desde la memoria en lugar de llamar a la IA nuevamente. Las ediciones del glosario y los cambios en el preajuste de cumplimiento invalidan automáticamente las traducciones en caché afectadas.','Enable block-level translation cache reuse across posts'=>'Habilitar reutilización de caché de traducción a nivel de bloque en varias publicaciones','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actualmente se omite para publicaciones que usan marcadores de atributos de comentario de bloque (campos wp:details, resumen, etc.) — estos pasan a la ruta de traducción de llamada única existente.','Cached block translations'=>'Traducciones de bloques en caché','Block translation reuses'=>'Reutilizaciones de traducción de bloques','(avg %.1f hits/block)'=>'(promedio %.1f hits/bloque)','Oldest cached block'=>'Bloque en caché más antiguo','Most recent cached block'=>'Bloque en caché más reciente','Approximate size'=>'Tamaño aproximado','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'¿Borrar toda la Memoria de Traducción? Las traducciones futuras reconstruirán la caché a medida que se ejecuten.','Clear Translation Memory'=>'Borrar Memoria de Traducción','API Response Cache setting saved.'=>'Configuración de caché de respuesta API guardada.','Translation Memory setting saved.'=>'Configuración de memoria de traducción guardada.','AI cache cleared. %d entry was removed.'=>'Caché de IA limpiada. Se eliminó %d entrada.' . "\0" . 'Caché de IA limpiada. Se eliminaron %d entradas.','Translation Memory cleared. %d cached block was removed.'=>'Memoria de traducción borrada. Se eliminó %d bloque en caché.' . "\0" . 'Memoria de traducción borrada. Se eliminaron %d bloques en caché.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge es una solución completa de SEO multilingüe. No se requiere ningún plugin adicional de SEO.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Si tienes instalado un plugin SEO general, este panel muestra cómo LF se adapta para evitar salidas duplicadas. El objetivo es evitar colisiones, no cooperación. LF siempre proporciona la capa SEO multilingüe (hreflang, og:locale, esquema inLanguage) que requiere conocimiento de la configuración de enrutamiento de LF para producirse correctamente.','Installed SEO plugins'=>'Plugins SEO instalados','Plugin'=>'Complemento','Status'=>'Estado','✓ Active'=>'✓ Activo','— Not detected'=>'— No detectado','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'No se detectaron plugins de SEO en conflicto. Lingua Forge maneja toda la salida de SEO de forma independiente.','What LF provides — and collision avoidance'=>'Lo que proporciona LF — y prevención de colisiones','Feature'=>'Función','LF provides'=>'LF proporciona','When another SEO plugin is installed'=>'Cuando se instala otro plugin SEO','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Desactivado (por configuración)','✓ LF outputs — plugin hreflang suppressed'=>'✓ Salidas LF — plugin hreflang suprimido','✓ LF outputs'=>'✓ Salidas LF','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF proporciona hreflang precisos para cada idioma configurado, incluido x-default. Los plugins de SEO generales no tienen acceso a la configuración de enrutamiento de LF y producirían hreflang basados en suposiciones incorrectas de URL. LF suprime su salida mediante filtro para evitar colisiones.','Suppressed: %s.'=>'Suprimido: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Desactivado (configuración de modo)','→ Locale tags only — deferring base OG to plugin'=>'→ Solo etiquetas de idioma — aplazando OG base a plugin','→ Locale tags only (manual setting)'=>'→ Solo etiquetas de idioma (configuración manual)','✓ LF outputs full OG + Twitter Cards'=>'✓ Salidas LF OG completo + Tarjetas de Twitter','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF siempre añade og:locale y og:locale:alternate — las señales multilingües que ningún plugin SEO puede producir correctamente. Para el conjunto OG base (og:title, og:description, og:image), LF lo genera cuando no hay otro plugin presente. Cuando se instala un plugin SEO, LF omite el conjunto base para evitar etiquetas duplicadas — no porque el plugin sea "mejor", sino porque la duplicación no aporta valor.','Schema.org JSON-LD'=>'JSON-LD de Schema.org','— Deferred to plugin'=>'— Relegado al plugin','✓ LF outputs Article / WebPage / WebSite'=>'✓ Salidas LF Artículo / Página Web / Sitio Web','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF genera JSON-LD multilingüe con anotaciones inLanguage vinculadas a su configuración de enrutamiento de idiomas. Cuando se instala un plugin de SEO, LF desactiva su propio esquema por completo: los gráficos JSON-LD duplicados producen errores de validación y no hay una forma sencilla de complementar un gráfico existente.','XML Sitemap'=>'Mapa del sitio XML','✓ Active at /lf-sitemap.xml'=>'✓ Activo en /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genera su propio mapa del sitio con alternativos xhtml:link para todos los grupos de traducción. Cuando se instala un plugin SEO, genera un mapa del sitio separado — ambos coexisten de forma independiente. Envía ambos a Google Search Console: el mapa del sitio del plugin SEO para descubrimiento de contenido, el mapa del sitio de LF para señales de relación de idioma.','Canonical tag'=>'Etiqueta canónica','✓ WP canonical replaced (self-referencing)'=>'✓ Se reemplazó el canonical de WP (auto-referenciado)','WP core canonical active (hreflang disabled)'=>'Canonical de WP core activo (hreflang desactivado)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF elimina la etiqueta canónica principal de WordPress y la reemplaza con una canónica que se refiere a la URL correcta con prefijo de idioma. Cuando un plugin de SEO de terceros (Yoast, Rank Math, AIOSEO, SEOPress) está activo, LF delega la gestión canónica a ese plugin por completo.','Legacy lf-social-share mu-plugin'=>'Plugin mu legada lf-social-share','The lf-social-share mu-plugin is active.'=>'El plugin mu lf-social-share está activo.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Los módulos integrados de Compartir en Redes Sociales y Open Graph de Lingua Forge cubren toda la funcionalidad que proporciona el plugin mu, además de soporte multilingüe para og:locale. Puedes desactivar con seguridad el plugin mu.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Etiquetas OG/Twitter Card: gestionadas por el módulo Open Graph de LF (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Compartir en bloque de iconos sociales: URLs: gestionado por la función integrada de Compartir en redes sociales de LF (SEO → Compartir en redes sociales)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'acciones JS nativas/automáticas/copiar: gestionadas por LF\'s social-share.js','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Mientras está activo, el plugin mu maneja el conjunto base de OG y LF emite solo etiquetas de idioma (modo automático). Quitar esto cambia LF a modo completo de OG automáticamente.','Debug Files'=>'Archivos de depuración','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Cuando la depuración de registros está habilitada (a través del interruptor a continuación o definiendo LINGUAFORGE_AI_DEBUG en wp-config.php), las funciones de traducción y traducción de plantillas FSE escriben sus solicitudes y respuestas de AI en disco para solucionar problemas. Usa esta sección para monitorear esa salida y borrarla una vez que tengas lo que necesitas; los archivos pueden crecer rápidamente en páginas grandes. Configura el directorio de destino a través del filtro linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Archivos de depuración borrados. Se eliminó %d archivo.' . "\0" . 'Archivos de depuración borrados. Se eliminaron %d archivos.','Debug logging enabled.'=>'Registro de depuración habilitado.','Debug logging disabled.'=>'Registro de depuración deshabilitado.','Debug logging'=>'Depuración','Write AI prompts and responses to disk for troubleshooting'=>'Escribir solicitudes y respuestas de AI en disco para solucionar problemas','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzado ACTIVADO por la constante LINGUAFORGE_AI_DEBUG en wp-config.php. Elimina esa línea para controlar este interruptor desde aquí.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzado DESACTIVADO por la constante LINGUAFORGE_AI_DEBUG en wp-config.php. Elimina esa línea para controlar este interruptor desde aquí.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Los archivos se almacenan en el directorio a continuación. Útil para diagnosticar problemas de traducción; desactívalo una vez que tengas lo que necesitas para que los archivos no se acumulen. También puedes forzar esto desde wp-config.php con `define( \'LINGUAFORGE_AI_DEBUG\', true );` que anula el interruptor.','Currently:'=>'Actualmente:','✓ Enabled'=>'✓ Activado','✗ Disabled'=>'✗ Desactivado','Directory'=>'Directorio','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra con linguaforge_debug_dir para redirigir la salida de depuración a una ubicación no pública.','Files'=>'Archivos','.txt file(s) in the directory'=>'.txt archivo(s) en el directorio','Save Debug Setting'=>'Guardar configuración de depuración','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'¿Eliminar todos los archivos .txt en el directorio de depuración? El directorio en sí permanecerá para que futuras escrituras de depuración sigan llegando de manera limpia.','Clear Debug Files'=>'Borrar archivos de depuración','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genera etiquetas <link rel="alternate" hreflang> para cada idioma configurado en cada página, incluyendo x-default que apunta al idioma fuente. Este es la señal principal de SEO multilingüe para Google y otros motores de búsqueda — no se requiere ningún plugin adicional de SEO.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Cuando Yoast SEO, Rank Math, All in One SEO o SEOPress están activos, Lingua Forge suprime automáticamente su salida hreflang mediante filtro. Los plugins SEO generales generan hreflang basados en una estructura de URL de un solo idioma y no pueden tener en cuenta tu configuración de enrutamiento multilingüe; la salida de LF siempre es correcta.','Hreflang settings saved.'=>'Configuraciones hreflang guardadas.','Hreflang output'=>'Salida hreflang','Output hreflang tags in wp_head'=>'Generar etiquetas hreflang en wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Desactivar solo para sitios sin cabeza o implementaciones completamente personalizadas de hreflang. Cuando está desactivado, LF ya no elimina la etiqueta canónica del núcleo de WordPress y ya no suprime la salida hreflang del plugin SEO.','Current status'=>'Estado actual','✓ Hreflang active'=>'✓ Hreflang activo','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF está generando etiquetas hreflang y está reemplazando el canonical del núcleo de WordPress con un canonical que se autoreferencia para cada versión de idioma.','LF is suppressing hreflang output from: %s'=>'LF está suprimiendo la salida hreflang de: %s','Save Hreflang Settings'=>'Guardar configuración de Hreflang','Language Overrides'=>'Sobrescrituras de idioma','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carga archivos .mo compilados para sobrescribir cadenas de plugins de terceros para locales específicos — por ejemplo, una traducción personalizada de VikBooking que use "apartamento" en lugar de "habitación". Los archivos deben seguir la convención de nombres de WordPress: {textdomain}-{locale}.mo (ej. vikbooking-ca.mo). Se almacenan en la carpeta de cargas y sobreviven a actualizaciones del plugin.','Override file uploaded successfully.'=>'Archivo de sobrescritura cargado con éxito.','Override file deleted.'=>'Archivo de sobrescritura eliminado.','No file was selected.'=>'No se seleccionó ningún archivo.','Only .mo files are accepted.'=>'Solo se aceptan archivos .mo.','The upload failed — please try again.'=>'La carga falló — por favor, inténtalo de nuevo.','Could not save the file. Check that the uploads folder is writable.'=>'No se pudo guardar el archivo. Verifica que la carpeta de cargas tenga permisos de escritura.','Invalid filename.'=>'Nombre de archivo inválido.','Security check failed — file path is not permitted.'=>'Error de seguridad — ruta del archivo no permitida.','An unknown error occurred.'=>'Ocurrió un error desconocido.','Text domain / locale'=>'Dominio de texto / local','Size'=>'Tamaño','Delete all files for this override (both .mo and .po)?'=>'¿Eliminar todos los archivos de esta sobrescritura (tanto .mo como .po)?','Delete'=>'Eliminar','No override files uploaded yet.'=>'Aún no se han cargado archivos de sobrescritura.','Upload .mo file'=>'Cargar archivo .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Solo acepta archivos .mo compilados. El nombre del archivo debe seguir el patrón {textdomain}-{locale}.mo. La carga de un archivo con el mismo nombre que uno existente lo reemplazará.','Upload Override'=>'Cargar Sobrescritura','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copiar a Almacenamiento Seguro','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate almacena sus traducciones personalizadas en wp-content/languages/loco/ — una ubicación que puede ser borrada silenciosamente por una actualización del núcleo de WP, reinstalación del plugin, o si Loco Translate se elimina. Copiar archivos aquí los mueve al directorio Lingua Forge i18n-overrides, que persiste a través de todos esos eventos y se carga automáticamente en cada solicitud.','File copied to safe storage successfully.'=>'Archivo copiado a almacenamiento seguro con éxito.','Source file not found.'=>'Archivo fuente no encontrado.','Could not copy the file. Check that the uploads folder is writable.'=>'No se pudo copiar el archivo. Verifica que la carpeta de cargas tenga permisos de escritura.','Invalid file reference.'=>'Referencia de archivo inválida.','Type'=>'Tipo','✓ In safe storage'=>'✓ En almacenamiento seguro','Copy to safe storage'=>'Copiar a almacenamiento seguro','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Aún no se encuentran archivos personalizados de Loco Translate. Aparecen aquí una vez que guardas una traducción en Loco Translate.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge genera meta etiquetas Open Graph y Twitter Card para que las URLs compartidas muestren el idioma, título, descripción e imagen correctos en las plataformas sociales.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'A diferencia de hreflang — donde LF siempre anula otros plugins porque no pueden conocer tu configuración multilingüe — Open Graph es diferente: Yoast, Rank Math y plugins similares ya generan etiquetas OG correctas para tu contenido. Duplicarlas no aporta valor. En modo automático, LF detecta plugins SEO activos y añade solo lo que no puedan proporcionar: og:locale (idioma actual) y og:locale:alternate (todos los demás idiomas configurados).','Open Graph settings saved.'=>'Configuraciones de Open Graph guardadas.','Open Graph output'=>'Salida de Open Graph','Output Open Graph tags in wp_head'=>'Generar etiquetas Open Graph en wp_head','Output mode'=>'Modo de salida','Auto (recommended)'=>'Auto (recomendado)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detecta plugins SEO activos (Yoast, Rank Math, etc.) en tiempo de ejecución. Emite solo og:locale + og:locale:alternate cuando otro plugin ya genera el conjunto completo de OG; emite el conjunto completo cuando no se detecta ninguno.','Locale only'=>'Solo localización','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Siempre emitir solo og:locale y og:locale:alternate. Usar cuando otro plugin o tema maneja el conjunto completo de OG.','Full'=>'Completo','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Siempre emitir el conjunto completo de OG + Tarjeta de Twitter independientemente de otros plugins. Usar solo si ningún otro plugin genera etiquetas OG.','Disabled'=>'Desactivado','Do not output any OG tags.'=>'No mostrar ninguna etiqueta OG.','Default OG image'=>'Imagen OG predeterminada','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL de imagen de respaldo utilizada cuando una página no tiene imagen destacada, logotipo del sitio o icono del sitio. Se muestra en vistas previas sociales para archivos, el índice del blog y cualquier página singular sin miniatura.','— Disabled'=>'— Desactivado','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Activo — solo etiquetas de idioma (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Activo — OG completo + Tarjetas de Twitter','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Se detectó el plugin mu legada lf-social-share. LF delega el conjunto OG base al plugin y solo genera og:locale + og:locale:alternate. Puedes desactivar el plugin mu — LF\'s Social Share incorporado (pestaña SEO → Social Share) y Open Graph cubren la misma funcionalidad.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Plugins de SEO detectados: %s. LF solo está generando og:locale y og:locale:alternate; el plugin detectado maneja el conjunto completo de OG.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'No se detectó ningún plugin externo de OG. LF está generando el conjunto completo de OG + Twitter Card.','Save Open Graph Settings'=>'Guardar configuración de Open Graph','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge genera datos estructurados JSON-LD de Schema.org para que los motores de búsqueda entiendan tu tipo de contenido, idioma y metadatos. Esta es la forma principal de comunicar anotaciones inLanguage para contenido multilingüe a Google y otros rastreadores.','Schema output deferred.'=>'Salida de Schema aplazada.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s está activo y ya genera JSON-LD Schema.org. Lingua Forge ha desactivado su propia salida de esquema para evitar gráficos en conflicto. A diferencia de Open Graph — donde LF añade og:locale además de la salida de otro plugin — el esquema no puede ser complementado de forma limpia: los gráficos JSON-LD duplicados o superpuestos producen errores de validación. Desactiva la salida del esquema en el plugin detectado si quieres que LF maneje los datos estructurados.','Schema.org settings saved.'=>'Configuración de Schema.org guardada.','Schema.org output'=>'Salida de Schema.org','Output Schema.org JSON-LD in wp_head'=>'Salida del esquema JSON-LD de Schema.org en wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Bloqueado — hay un plugin de SEO en conflicto activo. Consulta el aviso anterior.','Article / WebPage'=>'Artículo / Página Web','Output Article or WebPage schema on singular posts and pages'=>'Generar esquema Article o WebPage en publicaciones y páginas singulares','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Las publicaciones de blog usan Artículo; todos los demás tipos de publicaciones y páginas usan Página Web. Incluye titular, descripción, inLanguage, url, datePublished, dateModified, imagen y publisher.','WebSite'=>'Sitio Web','Output WebSite schema on the front page and blog index'=>'Salida del esquema WebSite en la página principal y en el índice del blog','Includes site name, url, and inLanguage.'=>'Incluye nombre del sitio, url e inLanguage.','Product'=>'Producto','Output Product schema on WooCommerce product pages'=>'Generar esquema Product en páginas de productos WooCommerce','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Incluye nombre, descripción, inLanguage, url, imagen y una Oferta con precio, moneda del precio y disponibilidad. El precio y la disponibilidad provienen del producto en el idioma fuente (modelo de stock compartido).','Currently emitting'=>'Emitiendo actualmente','Article / WebPage — all singular posts and pages'=>'Artículo / Página Web — todas las publicaciones y páginas en singular','WebSite — front page / blog index'=>'Sitio Web — página principal / índice del blog','Product — WooCommerce product pages'=>'Producto — páginas de productos de WooCommerce','Nothing — all types disabled'=>'Nada — todos los tipos están desactivados','Save Schema.org Settings'=>'Guardar configuración de Schema.org','Blog / Editorial'=>'Blog / Editorial','Product / eCommerce'=>'Producto / Comercio electrónico','Landing / Short-form'=>'Página de destino / Forma corta','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtra por idioma y tipo de publicación, navega por tu contenido y haz clic en Analizar en cualquier elemento para realizar una auditoría SEO basada en reglas — longitud del título, descripción meta, recuento de palabras, estructura de encabezados, cobertura de texto alternativo de imágenes y enlaces internos.','Treat H2 as H1 equivalent'=>'Tratar H2 como equivalente a H1','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Habilitar cuando tu tema renderiza el título de la publicación como un H2 en lugar de un H1 (común en algunos temas de bloques). El analizador obtiene la página renderizada y, si no encuentra un H1 pero sí un H2, promueve el primer H2 a H1 para fines de puntuación.','Save analysis settings'=>'Guardar configuraciones de análisis','Per-Post Analysis'=>'Análisis por publicación','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Selecciona una publicación y realiza una auditoría SEO detallada para ver resultados por métrica y una puntuación para ese elemento específico.','Language'=>'Idioma','source'=>'fuente','All types'=>'Todos los tipos','Load content'=>'Cargar contenido','Batch Analysis'=>'Análisis por lotes','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Realiza una auditoría SEO completa en todas las publicaciones publicadas para uno o todos los idiomas activos. Las puntuaciones se guardan por publicación y se reflejan en las insignias de la columna de idioma en la lista de publicaciones.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Las páginas del sistema de WooCommerce (Tienda, Carrito, Pago, Mi cuenta) están excluidas — su contenido es gestionado por WooCommerce y no puede mejorarse mediante ediciones SEO.','Post type'=>'Tipo de publicación','Default profile'=>'Perfil predeterminado','— Auto-detect —'=>'— Detectar automáticamente —','Analyse all languages'=>'Analizar todos los idiomas','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'La detección automática asigna: productos WooCommerce → perfil de producto; la página de inicio estática → perfil de destino; todo lo demás → perfil de blog. Elija un perfil específico para anular esto en todas las publicaciones.','%d post'=>'%d publicación' . "\0" . '%d publicaciones','Last run: %s ago'=>'Última ejecución: hace %s','Never run'=>'Nunca ejecutes','avg'=>'promedio','(partial)'=>'(parcial)','Analyse'=>'Analizar','(no title) #%d'=>'(sin título) #%d','Invalid post ID.'=>'ID de publicación no válido.','Post not found or not published.'=>'No se encontró ni se publicó la publicación.','~%d min read'=>'~%d min de lectura' . "\0" . '~%d min de lectura','No title set.'=>'No se ha establecido ningún título.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'El título tiene %1$d caracteres — puede truncarse en los SERPs (intenta que sea menor de %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'El título tiene solo %d caracteres — intenta con al menos 10 caracteres.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Título de una sola palabra (%d caracteres) — agregar una segunda palabra mejora la claridad y la cobertura de palabras clave.','%1$d chars, %2$d words — good title.'=>'%1$d caracteres, %2$d palabras — buen título.','Using LF AI meta description.'=>'Usando meta descripción de AI de LF.','No LF meta description set — using excerpt/content.'=>'No se ha establecido una meta descripción en LF — se usa el extracto/contenido.','No meta description found. Generate one via the AI meta description feature.'=>'No se encontró ninguna meta descripción. Genera una mediante la función de meta descripción con IA.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d caracteres — demasiado corto (apunta a %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d caracteres — probablemente truncados en los resultados de búsqueda (mantener por debajo de %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d caracteres — bien, ligeramente por encima del ideal %2$d pero dentro del rango aceptado de %3$d caracteres. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d caracteres — longitud ideal. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d palabras — contenido muy delgado. Considera expandir a al menos %2$d palabras.','%1$d words — below recommended minimum of %2$d.'=>'%1$d palabras — por debajo del mínimo recomendado de %2$d.','%d words.'=>'%d palabras.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Modo H2-como-H1 habilitado — el título se cuenta como equivalente a H1. (Las etiquetas de encabezado no pudieron ser detectadas en la página renderizada; verifica que tu tema muestre correctamente el título.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'No se encontró ningún H1. Normalmente, el título de la publicación es el H1 — verifica que tu tema lo esté generando.','%d H1 tags found — a page should have exactly one H1.'=>'Se encontraron %d etiquetas H1 — una página debe tener exactamente una H1.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — sin H2, pero se encontraron %d subtítulos H3 (por ejemplo, encabezados de acordeón/detalles). La estructura es aceptable.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — contenido corto (%d párrafos), no se requieren subtítulos.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — sin subtítulos H2 (aceptable para este tipo de contenido).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — no se encontraron subtítulos H2 o H3. Agregar H2 mejora la estructura.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'No se encontraron imágenes en el contenido.','%1$d of %2$d image(s) missing alt text.'=>'%1$d de %2$d imágenes sin texto alternativo.','%d image(s), all have alt text.'=>'%d imágenes, todas tienen texto alternativo.','No links found. Internal links improve crawlability and user navigation.'=>'No se encontraron enlaces. Los enlaces internos mejoran la rastreabilidad y la navegación del usuario.','No links found.'=>'No se encontraron enlaces.','%d external link(s), no internal links. Add internal links to related content.'=>'%d enlaces externos, sin enlaces internos. Añade enlaces internos a contenido relacionado.','%d external link(s), no internal links.'=>'%d enlace(s) externo(s), sin enlaces internos.','%1$d internal, %2$d external.'=>'%1$d internos, %2$d externos.','Post not found.'=>'Publicación no encontrada.','No AI provider configured. Add an API key in Settings → API Keys.'=>'No se ha configurado ningún proveedor de IA. Añade una clave API en Configuración → Claves API.','No response from AI provider. Check your API key and try again.'=>'No hay respuesta del proveedor de IA. Verifica tu clave API y vuelve a intentarlo.','AI returned an unexpected response format. Please try again.'=>'La IA devolvió un formato de respuesta inesperado. Por favor, intenta de nuevo.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genera un sitemap XML dedicado en /lf-sitemap.xml que añade enlaces alternativos de idioma para todo tu contenido traducido. Este sitemap complementa el sitemap del núcleo de WordPress y cualquier sitemap de plugin de SEO — no los reemplaza.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'El sitemap del núcleo de WordPress lista todas las URLs de tu contenido. El sitemap de LF indica a los motores de búsqueda cómo se relacionan las versiones en diferentes idiomas mediante alternativos xhtml:link hreflang. Envía ambos a Google Search Console para una cobertura completa.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s está activo y genera su propio mapa del sitio. Ese mapa del sitio es separado del de LF. Ambos deben ser enviados a Google Search Console: el mapa del sitio del plugin SEO lista tu contenido; el mapa del sitio de LF añade los enlaces alternativos multilingües. El mapa del sitio de LF se anuncia automáticamente en robots.txt.','Sitemap settings saved.'=>'Configuración del sitemap guardada.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'La caché del sitemap se vació. Se regenerará en la próxima visita a la URL del sitemap.','Sitemap output'=>'Salida del sitemap','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Generar el mapa del sitio multilingüe en /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Cuando está habilitado, la URL del sitemap se anuncia automáticamente en robots.txt y se actualiza la caché cuando se guarda contenido traducido.','Sitemap URL'=>'URL del sitemap','Submit this URL to Google Search Console alongside your main sitemap.'=>'Envía esta URL a Google Search Console junto con tu mapa del sitio principal.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Aún no se ha generado. El sitemap se construye en la primera visita a la URL del sitemap y se almacena en caché durante 24 horas.','✓ Active — %d URL entry with language alternates'=>'✓ Activo — %d entrada de URL con alternancias de idioma' . "\0" . '✓ Activo — %d entradas de URL con alternancias de idioma','No translated content found. The sitemap will populate once posts have been translated.'=>'No se encontró contenido traducido. El sitemap se completará una vez que las publicaciones hayan sido traducidas.','Last generated: %s'=>'Última generación: %s','Save Sitemap Settings'=>'Guardar configuración del sitemap','Flush Sitemap Cache'=>'Vaciar caché del mapa del sitio','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Forza a que el mapa del sitio se regenere en la próxima solicitud. Úsalo después de importar en masa o editar manualmente las relaciones de traducción.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow es un protocolo abierto soportado por Bing, Yandex y otros motores de búsqueda. Cuando se publica o actualiza una publicación traducida, Lingua Forge notifica automáticamente a todos los motores participantes en un solo envío — sin sondeo, sin esperar al próximo rastreo de robots.txt.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow reemplaza los puntos finales de ping de sitemap obsoletos de Bing y Yandex. Google descubre los sitemaps a través de la directiva Sitemap: en robots.txt como antes.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Todas las URLs enviadas a IndexNow con éxito.','No translated URLs found to submit. Publish some translated posts first.'=>'No se encontraron URLs traducidas para enviar. Publica primero algunas publicaciones traducidas.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ La presentación a IndexNow falló. Verifica que el archivo de clave sea accesible públicamente (ver abajo) y prueba de nuevo.','Verification key'=>'Clave de verificación','Key file served automatically at: %s'=>'Archivo de clave servido automáticamente en: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'No se pudo generar la clave. Verifica que el sitio tenga acceso de escritura a las opciones de WordPress.','Key file status'=>'Estado del archivo de clave','✓ Key file is publicly reachable.'=>'✓ El archivo de clave es accesible públicamente.','✗ Key file is not reachable.'=>'✗ El archivo de clave no es accesible.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'Los motores IndexNow verifican el archivo clave antes de aceptar envíos. Si el archivo no es accesible, los envíos serán rechazados con un error 403.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Causas comunes: caché de página completa (bórrala), un plugin de seguridad que bloquea archivos .txt, o una regla personalizada en Nginx/Apache. El archivo es servido por LF en cada solicitud — no se escribe ningún archivo físico en el disco.','Submit all URLs'=>'Enviar todas las URLs','Submit all URLs via IndexNow'=>'Enviar todas las URLs vía IndexNow','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Envía todas las URLs publicadas y gestionadas por LF a IndexNow en un lote. La presentación automática ya se realiza en cada publicación/actualización — usa esto solo después de una importación masiva o al configurar IndexNow por primera vez.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google no participa en IndexNow. Descubre sitemaps a través de la directiva Sitemap: en robots.txt, que LF ya ha configurado. Utiliza Google Search Console para monitorear la cobertura de indexación.','Open Search Console →'=>'Abrir Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt actualizado con la directiva Sitemap.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ robots.txt físico encontrado. La directiva Sitemap de LF está presente.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Existe un archivo robots.txt físico en la raíz del sitio. El robots.txt virtual de WordPress — y el Sitemap de LF: filtro — son ignorados. El mapa del sitio de LF no se anuncia a los motores de búsqueda.','Add Sitemap directive to robots.txt'=>'Añadir directiva Sitemap a robots.txt','Appends the following line to your existing robots.txt: %s'=>'Agrega la siguiente línea a tu robots.txt existente: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS está establecido.','Add the following line to your robots.txt manually:'=>'Añade la siguiente línea a tu robots.txt manualmente:','View current robots.txt'=>'Ver robots.txt actual','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'No se encontró un archivo robots.txt físico. WordPress lo genera virtualmente y la directiva Sitemap de LF se incluye automáticamente.','The following directive is active in your virtual robots.txt:'=>'La siguiente directiva está activa en tu robots.txt virtual:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Las modificaciones de archivos están deshabilitadas (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'No se pudo escribir en robots.txt. Verifique los permisos del archivo.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge extiende el bloque de Iconos Sociales del núcleo de WordPress con URLs de compartición dinámicas. Configura el enlace de cualquier icono a un valor "share:" y LF lo reescribe a la URL de compartición correcta o acción de JavaScript en el momento de renderizar — sin necesidad de código personalizado o plugin de terceros.','Social Share settings saved.'=>'Configuraciones de Compartir en Redes Sociales guardadas.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'El plugin mu lf-social-share está activo. La función integrada de Compartir en Redes Sociales de Lingua Forge está inactiva — el plugin mu se encarga de reescribir las URLs de compartición y las acciones en JS.','Social Share'=>'Compartir en redes sociales','Enable Social Share URL rewriting for Social Icons blocks'=>'Habilitar la reescritura de URL de Compartir en redes sociales para bloques de iconos sociales','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Desactivado porque el plugin mu lf-social-share ya proporciona esta función.','Save Social Share Settings'=>'Guardar configuración de compartición social','How to use'=>'Cómo usar','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'En el editor de bloques, añade un bloque de iconos sociales. Para cada icono, abre la configuración del enlace e ingresa uno de los valores "share:" a continuación como la URL. En el frontend, LF lo reemplaza con la URL de compartición correcta para la página actual.','External share services'=>'Servicios de compartición externos','URL to enter'=>'URL a ingresar','Action'=>'Acción','Share on Facebook'=>'Compartir en Facebook','Post on X / Twitter'=>'Publicar en X / Twitter','Share on LinkedIn'=>'Compartir en LinkedIn','Send via WhatsApp'=>'Enviar vía WhatsApp','Send via Telegram'=>'Enviar vía Telegram','Submit to Reddit'=>'Enviar a Reddit','Pin on Pinterest'=>'Fijar en Pinterest','Share on Mastodon'=>'Compartir en Mastodon','Share via email (mailto:)'=>'Compartir por correo electrónico (mailto:)','JavaScript-powered actions'=>'Acciones impulsadas por JavaScript','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Copia la URL actual al portapapeles. Muestra una notificación "Enlace copiado" en caso de éxito.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Abrir la hoja de compartir web nativa del navegador (iOS, Android, algunos escritorios). Recurre a copiar al portapapeles si no es compatible.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Usar compartición nativa cuando esté disponible; volver a copiar al portapapeles. Recomendado por defecto para botones de "Compartir".','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'La URL de compartición siempre refleja la página actual — no es necesario ingresar manualmente la URL. El filtro linguaforge_social_share_url te permite sobrescribir la URL resuelta para cualquier servicio.','Configuration issue: WP site language has no content on this site'=>'Problema de configuración: el idioma del sitio WP no tiene contenido en este sitio','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'El idioma del sitio de WordPress (%1$s) se asigna al código de idioma "%2$s", pero ninguna entrada en este sitio está etiquetada con _lf_lang=%2$s. Esto causa que las consultas de productos de WooCommerce devuelvan cero resultados, que las imágenes de productos fallen y que todas las consultas de contenido filtrado por idioma se rompan.','Fix: go to'=>'Arreglar: ir a','Settings → General → Site Language'=>'Configuración → General → Idioma del sitio','and set it to one of your actual content languages (e.g. %s).'=>'y configúralo en uno de tus idiomas de contenido reales (por ejemplo, %s).','Environment'=>'Entorno','Lingua Forge version'=>'Versión de Lingua Forge','WordPress version'=>'Versión de WordPress','PHP version'=>'Versión de PHP','Active theme'=>'Tema activo','(FSE / block theme)'=>'(tema FSE / bloques)','(classic theme)'=>'(tema clásico)','URL structure'=>'Estructura de URL','Subdomain (de.example.com)'=>'Subdominio (de.ejemplo.com)','Path prefix (/de/)'=>'Prefijo de ruta (/de/)','WP instance language'=>'Idioma de la instancia de WP','not a content language — see notice above'=>'no es un idioma de contenido — ver aviso arriba','Primary content language'=>'Idioma principal del contenido','Active languages'=>'Idiomas activos','PHP max_execution_time'=>'Tiempo máximo de ejecución de PHP','No PHP limit'=>'Límite de PHP no establecido','(server/FPM timeout still applies)'=>'(el tiempo de espera del servidor/FPM aún aplica)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'La traducción de IA y el análisis por lotes pueden agotarse. Se recomienda 120s o más.','PHP memory_limit'=>'Límite de memoria de PHP','AI Configuration'=>'Configuración de IA','(active)'=>'(activo)','Configured'=>'Configurado','No key'=>'Sin clave','— AI features are disabled.'=>'— Las funciones de IA están deshabilitadas.','Add key →'=>'Agregar clave →','Light model'=>'Modelo ligero','Quality model'=>'Modelo de calidad','Active preset'=>'Preajuste activo','Daily quota'=>'Cuota diaria','Unlimited'=>'Ilimitado','requests / day'=>'Solicitudes / día','Permalink Structure'=>'Estructura de enlaces permanentes','Permalink structure is compatible with Lingua Forge path routing.'=>'La estructura de enlaces permanentes es compatible con el enrutamiento de rutas de Lingua Forge.','Plain permalinks are not supported.'=>'Los enlaces permanentes simples no son compatibles.','Path routing requires a post-name based permalink structure. Change it in'=>'El enrutamiento de rutas requiere una estructura de enlaces permanentes basada en el nombre de la publicación. Cámbialo en','Settings → Permalinks'=>'Configuración → Enlaces permanentes','Numeric permalink structure is not supported.'=>'La estructura de enlaces permanentes numéricos no es compatible.','Switch to a post-name based structure in'=>'Cambia a una estructura basada en el nombre de la publicación en','SEO Plugins'=>'Plugins de SEO','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'No se detectaron plugins de SEO de terceros. Lingua Forge maneja toda la salida de SEO multilingüe.','Active: %s.'=>'Activo: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Consulta Configuración → SEO → Compatibilidad para la tabla completa de comportamiento por función.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce no está activo.','Shop'=>'Tienda','Cart'=>'Carrito','Checkout'=>'Pagar','My Account'=>'Mi cuenta','WooCommerce version'=>'Versión de WooCommerce','Order storage'=>'Almacenamiento de pedidos','High-Performance Order Storage (HPOS)'=>'Almacenamiento de pedidos de alto rendimiento (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Tablas personalizadas — Los filtros LF post-meta no afectan los pedidos.','Shared / compatibility mode'=>'Modo compartido / de compatibilidad','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT sincronizados — transicional; Los filtros LF post-meta se aplican a la copia de CPT.','Legacy post-based (CPT)'=>'Basado en publicaciones heredadas (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Pedidos en wp_posts — asegúrese de excluir shop_order del enrutamiento LF.','WcPageBridge active'=>'WcPageBridge activo','Yes'=>'Sí','No — WooCommerce integration class not loaded'=>'No — clase de integración de WooCommerce no cargada','WooCommerce page translations'=>'Traducciones de páginas de WooCommerce','No secondary languages configured.'=>'No hay idiomas secundarios configurados.','Active Plugins'=>'Plugins activos','No active plugins detected.'=>'No se detectaron plugins activos.','Version'=>'Versión','_lf_lang Coverage'=>'Cobertura _lf_lang','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Las publicaciones sin _lf_lang son invisibles para todos los filtros de idioma de Lingua Forge. Esto puede ocurrir cuando el contenido se importa o crea antes de activar el plugin.','All published posts have a _lf_lang value. No gaps detected.'=>'Todas las publicaciones publicadas tienen un valor _lf_lang. No se detectaron brechas.','Missing'=>'Faltante','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Excluir este tipo de publicación del enrutamiento por idioma — sus publicaciones ya no aparecerán aquí ni recibirán _lf_lang. Esto no se puede deshacer automáticamente.','Exclude from routing'=>'Excluir del enrutamiento','excluded from routing'=>'excluido del enrutamiento','Destructive action — read before proceeding'=>'Acción destructiva — lee antes de proceder','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Repare las etiquetas en cada publicación enrutable listada arriba con _lf_lang = %s. Las publicaciones en tipos de publicación excluidos del enrutamiento no se modifican. Ejecute esto solo después de importar contenido o en la activación inicial — no lo use como una herramienta de reasignación de idioma en masa.','Repair — assign _lf_lang = %s to all routable posts above'=>'Reparar — asignar _lf_lang = %s a todas las publicaciones enrutables arriba','Rewrite Rules'=>'Reglas de reescritura','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Entradas propiedad de LF actualmente registradas en $wp_rewrite->extra_rules_top. Útil para diagnosticar errores 404 o conflictos de enrutamiento. Copie estos al presentar un informe de error.','%d rule registered'=>'%d regla registrada' . "\0" . '%d reglas registradas','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'No se encontraron reglas de reescritura LF. Actualiza los enlaces permanentes si esto es inesperado.','Debug Info'=>'Información de depuración','Copy and paste into a GitHub issue or support request.'=>'Copie y pegue en un problema de GitHub o solicitud de soporte.','Copy system info'=>'Copiar información del sistema','Copied!'=>'¡Copiado!','Repairing…'=>'Reparando…','Repair failed.'=>'La reparación falló.','Network error.'=>'Error de red.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'¿Excluir este tipo de publicación del enrutamiento por idioma? Sus publicaciones ya no aparecerán en esta lista ni recibirán _lf_lang. Puedes revertir esto en Configuración → Enrutador → Exclusiones de filtro de consulta.','Excluding…'=>'Excluyendo…','Failed to save exclusion.'=>'Error al guardar la exclusión.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d publicación etiquetada con _lf_lang = %2$s.' . "\0" . '%1$d publicaciones etiquetadas con _lf_lang = %2$s.','Uninstall Behaviour'=>'Desinstalar comportamiento','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla qué sucede cuando un administrador elimina el plugin desde Plugins → Plugins instalados → Eliminar. La configuración del plugin y las cachés de AI siempre se eliminan. Las asignaciones de idioma y las relaciones de traducción se mantienen por defecto para que una desinstalación accidental o una reinstalación puedan continuar donde lo dejaron.','Uninstall setting saved.'=>'Configuración de desinstalación guardada.','Delete content data on uninstall'=>'Eliminar datos de contenido al desinstalar','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'También elimina asignaciones de idioma, relaciones de traducción, meta descripciones, glosario y Memoria de Traducción cuando se desinstala el plugin.','Warning:'=>'Advertencia:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si se marca, desinstalar el plugin eliminará permanentemente todas las asignaciones de idioma, relaciones de traducción, meta descripciones, preajustes por página, el glosario de AI y la Memoria de Traducción para cada publicación en este sitio. Esto no se puede deshacer. No marque esta opción a menos que esté eliminando completamente el soporte multilingüe del sitio.','Save Uninstall Setting'=>'Guardar configuración de desinstalación','Today'=>'Hoy','Last 7 days'=>'Últimos 7 días','Last 30 days'=>'Últimos 30 días','All time'=>'Todo el tiempo','AI Usage'=>'Uso de IA','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'El consumo de tokens se agrupa por función, proveedor y modelo. Se registra en cada llamada AI exitosa; las pruebas de conexión se excluyen para no distorsionar los totales.','Check your account, billing, or remaining credits directly on the provider console:'=>'Verifica tu cuenta, facturación o créditos restantes directamente en la consola del proveedor:','Anthropic Console'=>'Consola de Anthropic','OpenAI Platform'=>'Plataforma OpenAI','Google AI Studio'=>'Estudio de IA de Google','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Aún no se ha registrado uso de IA. Una vez que un editor realice una traducción, genere una meta descripción o utilice cualquier otra función de IA, los totales aparecerán aquí.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No se ha registrado uso de IA en la ventana seleccionada (%s). Elige un rango más amplio arriba.','Provider'=>'Proveedor','Model'=>'Modelo','Requests'=>'Solicitudes','Input tokens'=>'Tokens de entrada','Output tokens'=>'Tokens de salida','Total tokens'=>'Tokens totales','Total'=>'Total','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge añade propiedades específicas de Open Graph para WooCommerce en las páginas de productos para que compartir una URL de producto en Facebook, Pinterest y plataformas similares muestre el tipo de producto correcto, precio y disponibilidad.','WooCommerce SEO settings saved.'=>'Configuraciones SEO de WooCommerce guardadas.','Product Open Graph'=>'Open Graph del producto','Add WooCommerce product tags to Open Graph output'=>'Añadir etiquetas de productos WooCommerce a la salida de Open Graph','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Cuando está habilitado, Lingua Forge genera las siguientes etiquetas meta adicionales en páginas de productos: og:type=product, og:price:amount, og:price:currency, og:availability, y sus equivalentes en el espacio de nombres product: usados por Facebook Catalog.','Tags emitted'=>'Etiquetas emitidas','Tag'=>'Etiqueta','Value source'=>'Fuente del valor','"product" (replaces "article")'=>'"producto" (reemplaza "artículo")','WooCommerce product price'=>'Precio del producto WooCommerce','WooCommerce store currency'=>'Moneda de la tienda WooCommerce','instock / oos / pending from WC stock status'=>'en stock / agotado / pendiente desde el estado de stock de WC','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'El precio y la disponibilidad siempre reflejan el producto en el idioma fuente (modelo de stock compartido). Las etiquetas solo se muestran cuando el módulo Open Graph de LF está configurado en "Completo" o "Automático" sin detectar un plugin SEO en conflicto.','Save WooCommerce SEO Settings'=>'Guardar configuración de SEO de WooCommerce','AI Provider'=>'Proveedor IA','AI Usage & Cache'=>'Uso de IA y Caché','API Keys'=>'Claves API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Las claves se cifran con AES-256-CBC antes de almacenarlas en la base de datos de WordPress. El secreto de cifrado se deriva de tus sales de autenticación de WordPress (wp-config.php), por lo que las claves en texto plano nunca llegan a la base de datos.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'Las credenciales de la API son gestionadas por WordPress en %s. Lingua Forge no almacena ninguna clave.','Settings → Connectors'=>'Configuración → Conectores','API Key'=>'Clave API','Paste your API key…'=>'Pega tu clave API…','✓ Configured'=>'Configurado ✓','✗ Not configured'=>'No configurado ✗','Test connection'=>'Probar conexión','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deja en blanco para mantener la clave existente. Ingresa un nuevo valor para reemplazarla.','Remove stored key'=>'Eliminar clave almacenada','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Esta clave actualmente la proporciona un servidor %s y no puede ser eliminada aquí. Ingresa una nueva clave arriba para sobrescribirla con un valor de la base de datos.','environment variable'=>'variable de entorno','PHP constant'=>'constante de PHP','Alternative (server-side):'=>'Alternativa (lado del servidor):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'También puedes definir claves como constantes o variables de entorno (por ejemplo, en wp-config.php). Esas fuentes se usan automáticamente como respaldo cuando no se almacena una clave en la base de datos.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Para usar un secreto de cifrado personalizado (en lugar del valor derivado wp_salt), añade esto a wp-config.php:','Unknown provider.'=>'Proveedor desconocido.','No API key configured for this provider.'=>'No hay una clave API configurada para este proveedor.','Could not instantiate the provider.'=>'No se pudo instanciar el proveedor.','Provider returned no response. Check the WordPress error log for details.'=>'El proveedor no devolvió respuesta. Verifique el registro de errores de WordPress para más detalles.','Enter a model identifier to test.'=>'Introduce un identificador de modelo para probar.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'No se encontró ninguna entrada o página publicada para probar — publica contenido primero, o prueba Traducción rápida directamente.','(untitled)'=>'(sin título)','Prompt template not found.'=>'Plantilla de prompt no encontrada.','Translation failed. Please try again.'=>'La traducción falló. Por favor, inténtalo de nuevo.','The sample post has no visible text content to translate.'=>'La entrada de ejemplo no tiene contenido de texto visible para traducir.','Chunk prompt template not found.'=>'Plantilla de prompt de fragmento no encontrada.','Model returned no response. Check the WordPress error log for details.'=>'El modelo no devolvió respuesta. Comprueba el registro de errores de WordPress para obtener más detalles.','Behavior'=>'Comportamiento','Block Editor'=>'Editor de bloques','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restringe por defecto dos funciones de Gutenberg para mantener la coherencia editorial en todos los idiomas. Participa aquí si necesitas capacidades completas de Gutenberg / FSE.','Block locking'=>'Bloqueo de bloques','Allow editors to lock individual blocks'=>'Permitir a los editores bloquear bloques individuales','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Vuelve a habilitar canLockBlocks de Gutenberg. Útil para plantillas editoriales que necesitan evitar que los colaboradores muevan o eliminen bloques específicos.','Template mode'=>'Modo de plantilla','Allow Gutenberg template-editing mode on post screens'=>'Permitir modo de edición de plantilla de Gutenberg en pantallas de publicaciones','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Vuelve a habilitar supportsTemplateMode. Esencial en flujos de trabajo de Edición Completa del Sitio donde las anulaciones de plantilla a nivel de publicación son intencionales.','Compliance Preset'=>'Preajuste de cumplimiento','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modo de preservación estricta para contenido legal, regulatorio, médico o técnico. Cuando está activado, cada función de IA usa una temperatura de muestreo baja y añade el apéndice abajo a su prompt del sistema — la terminología, números de artículos, unidades, nombres de marcas y lenguaje regulatorio se preservan exactamente en lugar de parafrasear.','Global AI preset'=>'Preajuste global de IA','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, por función','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Establece el comportamiento predeterminado de IA para todas las funciones en todo el sitio. Las publicaciones individuales pueden sobrescribir esto para Traducción y Generación de Contenido a través del cuadro meta de Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'El modo estándar usa la temperatura ajustada de cada función: Traducción T=0.2 (preciso), Traducción rápida T=0.4, Generador de contenido T=0.6 (creativo). Los otros preajustes aplican una temperatura fija en todas las funciones.','Technical / Scientific instructions'=>'Instrucciones técnicas / científicas','Legal / Compliance instructions'=>'Instrucciones legales / de cumplimiento','Creative / Marketing instructions'=>'Instrucciones creativas / de marketing','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deja en blanco para usar el valor predeterminado incorporado. Borrar una anulación guardada restaura el valor predeterminado en el próximo guardado.','View built-in default'=>'Ver valor predeterminado incorporado','Automatic Translation Backfill'=>'Relleno automático de traducciones','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Examina periódicamente las entradas que carecen de una traducción en un idioma activo y pone en cola una traducción de IA para cada brecha encontrada — la misma recuperación que ya puedes activar manualmente mediante "Traducir faltantes" o los comandos WP-CLI missing_translations/fill_translations, ejecutados automáticamente una vez cada hora.','Automatic backfill'=>'Relleno automático','Automatically translate posts missing a language version'=>'Traduce automáticamente entradas que carecen de una versión de idioma','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Deshabilitado por defecto. Esta función realiza solicitudes de proveedores de IA — y gasta el costo de API asociado — automáticamente y en segundo plano, sin confirmación por solicitud, para cada entrada publicada que no tenga una traducción en un idioma activo. Actívalo solo si deseas que cada brecha de contenido se traduzca sin supervisión; en caso contrario, usa "Traducir faltantes" o los comandos WP-CLI para traducir según tu propio horario.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'Los productos y variaciones de WooCommerce nunca se incluyen, independientemente de esta configuración. Una integración también puede bloquear tipos de entrada específicos mediante el filtro linguaforge_cpt_create_allowed.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'El botón "Sincronizar" en la columna Lang de la lista de entradas retraduce una entrada a todos los demás idiomas, incluyendo el idioma principal/fuente cuando se ejecuta desde una traducción. Esa dirección de retro-traducción está restringida por defecto para todos los tipos de entrada. (Los productos y variaciones de WooCommerce tienen su propia configuración separada a continuación — esta no los afecta.)','Secondary-language Sync'=>'Sincronización de idioma secundario','Allow "Sync" on a translated post to overwrite the primary post'=>'Permitir que "Sincronizar" en una entrada traducida sobrescriba la entrada principal','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Deshabilitado por defecto: hacer clic en "Sincronizar" en una traducción está bloqueado para no sobrescribir la entrada principal. La sincronización DESDE la entrada principal a cada traducción siempre está permitida independientemente de esta configuración. Actívalo solo si deseas intencionalmente que una traducción pueda convertirse en el nuevo contenido fuente.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'El producto del idioma principal es la fuente operativa de verdad de WooCommerce para precio, SKU y existencias, que siempre se sirven desde él independientemente de qué idioma vea un comprador. Esta es una configuración separada e independiente de la restricción general "Sincronizar" anterior — habilitar una no habilita la otra.','Allow "Sync" on a translated product to overwrite the primary product'=>'Permitir que "Sincronizar" en un producto traducido sobrescriba el producto principal','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Deshabilitado por defecto: hacer clic en "Sincronizar" en un producto WooCommerce traducido está bloqueado, ya que retrotraduce al título, descripción y extracto del producto principal. La sincronización DESDE el producto principal a cada traducción siempre está permitida independientemente de esta configuración. Actívalo solo si deseas intencionalmente que una traducción pueda convertirse en el nuevo contenido fuente.','General'=>'General','Light'=>'Ligero','Meta Description, Excerpt Generator, quick translate'=>'Meta descripción, Generador de extractos, traducción rápida','Quality'=>'Calidad','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Traducción de página completa, Generador de contenido (los modelos de nivel medio son completamente suficientes)','Active Provider'=>'Proveedor activo','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actualmente heredado de la constante %s. Seleccionar un valor aquí lo sobrescribirá.','WordPress AI Client — requirements:'=>'Requisitos del cliente de IA de WordPress:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'La traducción de página completa usa una salida restringida por esquema JSON. Esto requiere que un plugin de conector esté instalado y activo (no solo una clave API guardada en Configuración → Conectores). Si la traducción falla, revisa el registro de errores PHP para el error específico, o cambia a un proveedor incorporado.','Manage your account, review usage, or top up credits:'=>'Gestiona tu cuenta, revisa el uso o recarga créditos:','WordPress Connectors'=>'Conectores de WordPress','Models'=>'Modelos','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Las funciones están agrupadas en dos niveles. Ingresa el identificador exacto del modelo para cada nivel y proveedor. Deja un campo en blanco para usar el valor predeterminado incorporado (mostrado como marcador de posición). Solo se llaman los modelos del proveedor activo en tiempo de ejecución — configura los otros con anticipación si planeas cambiar.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Comience a escribir en cualquier campo para ver sugerencias del modelo, o use la tabla de referencia a continuación. Los modelos de calidad ligera y media (Haiku, GPT-4o mini, Gemini Flash) son completamente suficientes para traducción y generación de contenido — los modelos insignia "max" añaden costo con ganancia mínima de calidad para textos estructurados.','active'=>'activo','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'La selección de modelo es gestionada por WordPress en %s — Lingua Forge no almacena identificador de modelo para este proveedor.','overridden'=>'sobrescrito','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Traduce una muestra corta de tu entrada publicada más reciente con este modelo exacto — una llamada de API real y facturada.','Test model'=>'Modelo de prueba','Tip: to reset a model to the built-in default, clear the field and save.'=>'Consejo: para restablecer un modelo al valor predeterminado incorporado, borra el campo y guarda.','Available models reference'=>'Referencia de modelos disponibles','Model ID'=>'ID del modelo','Name'=>'Nombre','Tier'=>'Nivel','Notes'=>'Notas','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Este catálogo se actualiza con cada versión de Lingua Forge. Probar una conexión en la pestaña de Claves API también obtiene la lista de modelos en vivo del proveedor y actualiza las sugerencias anteriores.','Glossary'=>'Glosario','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabla de terminología gestionada por el usuario por par de idiomas. Las entradas se añaden al prompt del sistema de traducción para que la IA utilice términos preferidos de manera consistente — fundamental para vocabulario de dominio ("kWp", "PPA", "punto de interconexión"), nombres de marcas que no deben traducirse y frases regulatorias estandarizadas. Ambos campos de idioma son opcionales: deja en blanco "Idioma fuente" para aplicar la entrada independientemente del idioma desde el que estás traduciendo; deja en blanco "Idioma destino" para aplicarlo a todos los idiomas destino a la vez.','Glossary entry added.'=>'Entrada del glosario añadida.','Glossary entry removed.'=>'Entrada del glosario eliminada.','Could not add entry: source term and target term are required.'=>'No se pudo añadir la entrada: se requieren el término fuente y el término destino.','Could not save the glossary entry.'=>'No se pudo guardar la entrada del glosario.','Source language'=>'Idioma fuente','— Any —'=>'— Cualquiera —','Target language'=>'Idioma destino','— Any target —'=>'— Cualquier destino —','Filter'=>'Filtro','Reset'=>'Restablecer','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'No hay entradas en el glosario que coincidan con el filtro actual. Limpia el filtro para ver todas las entradas, o añade una nueva abajo.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Aún no hay entradas en el glosario. Añade una abajo para empezar a aplicar la terminología en las traducciones.','Source term'=>'Término fuente','Target term'=>'Término destino','Source lang'=>'Idioma fuente','Target lang'=>'Idioma destino','any'=>'cualquiera','Delete this glossary entry?'=>'¿Eliminar esta entrada del glosario?','Add new entry'=>'Añadir nueva entrada','The phrase as it appears in the source text.'=>'La frase tal como aparece en el texto fuente.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Cómo debe aparecer en la traducción. Escribe el mismo valor que el término fuente para indicar a la IA que lo conserve exactamente.','— Any source language —'=>'— Cualquier idioma fuente —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deja en blanco para nombres de marcas y términos independientes del idioma que deben mantenerse sin importar desde qué idioma se traduzca.','— Any target language —'=>'— Cualquier idioma destino —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deja en blanco para aplicar esta entrada a todos los idiomas destino — ideal para nombres de marcas, abreviaturas y términos que deben mantenerse exactamente en cada traducción.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contexto opcional para editores (por ejemplo, "ASIC = Circuito Integrado de Aplicación Específica; conservar en inglés en contextos técnicos").','Add entry'=>'Añadir entrada','Limits'=>'Límites','Authors and above (edit_published_posts)'=>'Autores y superiores (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Colaboradores y superiores — predeterminado (edit_posts)','Editors and above (edit_others_posts)'=>'Editores y superiores (edit_others_posts)','Administrators only (manage_options)'=>'Solo administradores (manage_options)','AI Limits & Security'=>'Límites y Seguridad de IA','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita cuánto puede generar la IA en el sitio y restringe qué roles de usuario pueden activar llamadas pagadas a la IA. Se superpone al límite de tasa por usuario (30 solicitudes / minuto, codificado en duro) que ya protege contra bucles descontrolados de un solo usuario.','Daily request limit'=>'Límite diario de solicitudes','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Techo en toda la web para solicitudes de IA por día UTC (cuenta tanto las traducciones en la barra de herramientas como las revisiones de bloques). El contador se reinicia a la medianoche UTC. Pon en 0 para desactivar el límite.','Minimum role'=>'Rol mínimo','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacidad de WordPress más baja permitida para activar funciones de IA. Restringir esto en sitios con múltiples autores evita que Colaboradores o cuentas de prueba ejecuten llamadas pagadas a la IA. Sobrescribe por función mediante el filtro linguaforge_required_capability.','Translation Limits'=>'Límites de Traducción','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controla cuánto contenido se envía a la IA y cuán grande puede ser la respuesta. Deja en blanco para usar el valor predeterminado incorporado (mostrado como marcador de posición). Aumenta estos valores si las páginas grandes se cortan; bájalos para reducir costos de API.','Model tier'=>'Nivel del modelo','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Calidad (predeterminado — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Ligero (rápido y rentable — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Qué nivel de modelo usar para traducción de página completa. La calidad usa el modelo configurado en la tabla de Modelos arriba y se recomienda para traducciones precisas y de formato largo. Cambia a Ligero solo si la velocidad o el costo son prioritarios y el contenido es corto.','Max output tokens'=>'Tokens máximos de salida','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Número máximo de tokens que la IA puede producir en una sola respuesta de traducción. Si una traducción se corta silenciosamente al final, aumenta este valor. Predeterminado: 16,000.','Max input characters'=>'Caracteres máximos de entrada','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Número máximo de caracteres del contenido de la publicación enviado a la IA. 0 significa sin límite — siempre se envía el contenido completo (recomendado). Establece un valor distinto de cero solo si tu proveedor tiene una ventana de contexto ajustada. Se escribe una advertencia en el registro de errores de PHP cada vez que se recorta el contenido.','Quick Translation'=>' Traducción rápida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traducción rápida se usa en modo fragmento/pedazo — pasajes cortos traducidos a demanda desde la barra de herramientas, editor o popovers de bloques. Utiliza una configuración separada y más ligera que la traducción de página completa para mantener las respuestas rápidas y rentables.','Light (default — fast and cost-effective)'=>'Ligero (predeterminado — rápido y rentable)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Calidad (Soneto / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'El nivel Ligero usa el modelo rápido configurado en la tabla de Modelos arriba (predeterminado: Haiku / Flash). Cambia a Calidad si necesitas la misma precisión de traducción que en modo de página completa para fragmentos.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Número máximo de tokens que la IA puede producir por traducción rápida. Predeterminado: 2 000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Número máximo de caracteres aceptados desde el campo de entrada. Predeterminado: 8 000.','Content Generator'=>'Generador de contenido','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla el presupuesto de tokens y los límites de entrada para la función Generador de contenido de IA. Deja los campos en blanco para usar los valores predeterminados integrados.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Número máximo de tokens que la IA puede producir por ejecución de generación. Aumenta esto si se cortan artículos completos. Predeterminado: 8 192.','Max hints characters'=>'Máx. caracteres de pistas','Maximum characters read from the Hints field. Default: 2 000.'=>'Número máximo de caracteres leídos del campo de Pistas. Predeterminado: 2 000.','Max context characters'=>'Máx. caracteres de contexto','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Número máximo de caracteres del contenido de la publicación existente pasado a la IA como contexto semilla cuando no se proporcionan Pistas. Predeterminado: 6 000.','Maintenance'=>'Mantenimiento','Router'=>'Enrutador','Primary language saved.'=>'Idioma principal guardado.','Permalink rules flushed successfully.'=>'Reglas de enlaces permanentes eliminadas con éxito.','Language uninstalled. %d post deleted.'=>'Idioma desinstalado. Se eliminaron %d publicaciones.' . "\0" . 'Idioma desinstalado. Se eliminaron %d publicaciones.','%d locale file removed.'=>'Archivo de idioma eliminado %d.' . "\0" . 'Archivos de idioma eliminados %d.','%d pattern translation removed.'=>'%d traducción de patrón eliminada.' . "\0" . 'Se eliminaron %d traducciones de patrón.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'No se pudo eliminar automáticamente %d archivo(s) de idioma (DISALLOW_FILE_MODS está activado). Elimínalo manualmente desde tu servidor o WP-CLI: wp language core uninstall <locale>.' . "\0" . 'No se pudieron eliminar automáticamente %d archivos de idioma (DISALLOW_FILE_MODS está activado). Elimínalos manualmente desde tu servidor o WP-CLI: wp language core uninstall <locale>.','Primary Language'=>'Idioma principal','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'El idioma principal siempre se sirve en la raíz de su sitio: sin prefijo en la URL en modo de ruta, sin subdominio de idioma en modo de subdominio. Todos los demás idiomas usan un prefijo de ruta /lang/ (por ejemplo, example.com/de/) o un subdominio de idioma (por ejemplo, de.ejemplo.com), dependiendo de la configuración de estructura de URL a continuación.','Primary language'=>'Idioma principal','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Después de cambiar el idioma principal, actualiza los enlaces permanentes (sección a continuación) para que la enrutación de URL se actualice.','Path prefix — example.com/de/'=>'Prefijo de ruta — ejemplo.com/de/','Subdomain — de.example.com/'=>'Subdominio — de.ejemplo.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'El modo de subdominio requiere que tu servidor web apunte todos los subdominios de idioma (por ejemplo, de.ejemplo.com) a esta instalación de WordPress. Después de cambiar de modo, actualiza las reglas de enlaces permanentes y borra cualquier caché. Si la URL de inicio incluye www (por ejemplo, www.ejemplo.com), usa el filtro lf_base_domain para establecer el dominio raíz sin www para que los subdominios se construyan correctamente.','Browser language redirect'=>'Redirección por idioma del navegador','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirige a los visitantes a su idioma preferido según la cabecera Accept-Language del navegador','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Cuando está habilitado, los visitantes que visitan por primera vez sin cookie de idioma y sin prefijo de idioma en la URL son redirigidos a la versión en el idioma más cercano. La redirección se omite si el idioma preferido del navegador no está entre los idiomas activos del enrutador. Una vez que un visitante selecciona un idioma mediante el selector, la cookie tiene prioridad y se ignora la cabecera del navegador en futuras visitas.','Query Filter Exclusions'=>'Exclusiones de filtros de consulta','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge limita las instancias secundarias de WP_Query (widgets de barra lateral, bloques de plantilla, búsquedas de plugins) al idioma activo inyectando una restricción meta _lf_lang. Los tipos de publicaciones listados aquí están excluidos de esa restricción — sus consultas siempre están sin filtrar.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7 (wpcf7_contact_form), contactos de Flamingo y mensajes entrantes (flamingo_contact, flamingo_inbound), y almacenamiento de sincronización del paquete de idioma de WordPress (wp_sync_storage) se excluyen automáticamente. Agrega otros tipos de publicaciones de terceros cuyo contenido no debe filtrarse por idioma, uno por línea o separado por comas.','Excluded post types'=>'Tipos de publicaciones excluidos','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Slugs de tipo de publicación separados por comas o saltos de línea. Los cambios tienen efecto inmediatamente al guardar — no es necesario actualizar los enlaces permanentes.','WooCommerce Integration'=>'Integración de WooCommerce','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Controla cómo Lingua Forge se integra con el procesamiento de pedidos de WooCommerce.','Order line item source mapping'=>'Mapeo de origen de la línea de pedido','Normalize order line item product IDs to the source-language product at checkout'=>'Normaliza los IDs de productos de las líneas de pedido al producto en el idioma fuente en la compra','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Cuando está habilitado (recomendado), el ID del producto almacenado en cada línea de pedido de WooCommerce se establece en el producto en el idioma fuente. Esto asegura que los conteos de ventas totales, las filas de ingresos en WC Analytics y las exportaciones de ERP de terceros hagan referencia a un ID de producto por SKU en lugar de uno por versión de idioma. Contrapartida: los enlaces "Ver producto" en los correos electrónicos de pedido y en Mi Cuenta llevan a la página en el idioma fuente. Desactívalo solo si un sistema conectado depende de IDs de productos traducidos en los pedidos. Usa el filtro linguaforge_wc_order_item_source_mapping para sobrescribir por ítem.','Save Router Settings'=>'Guardar configuración del enrutador','Flush Permalinks'=>'Actualizar enlaces permanentes','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera las reglas de reescritura de WordPress para que los prefijos de URL, los slugs específicos del idioma y las reescrituras de archivos estén sincronizados. Es necesario después de cambiar el idioma principal o agregar soporte para nuevos idiomas.','Flush Permalink Rules'=>'Actualizar reglas de enlaces permanentes','Active Languages'=>'Idiomas activos','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Idiomas actualmente conocidos por el enrutador (derivados de los paquetes de idioma de WordPress instalados más el idioma principal). Instala paquetes de idioma adicionales en la sección inferior para hacer más idiomas disponibles para el enrutamiento y la traducción.','%d locale pack installed.'=>'%d paquete de idioma instalado.' . "\0" . '%d paquetes de idioma instalados.','Install a Language'=>'Instalar un idioma','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Descarga e instala un paquete de idioma de WordPress directamente desde WordPress.org. Una vez instalado, el idioma estará disponible para el enrutamiento de URL y el flujo de trabajo de traducción AI. La lista de idiomas disponibles se obtiene bajo demanda — haz clic en el botón de abajo para cargarla.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'La instalación de idiomas está deshabilitada en este servidor. La constante DISALLOW_FILE_MODS está configurada en wp-config.php. Instala manualmente los paquetes de idioma mediante WP-CLI: wp language core install de_DE','Load available languages'=>'Cargar idiomas disponibles','— select a language —'=>'— selecciona un idioma —','Install'=>'Instalar','Language Setup'=>'Configuración de idioma','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'No hay idiomas secundarios configurados. Instala un paquete de idioma arriba para habilitar la estructura de plantillas.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecciona un idioma para gestionar sus plantillas FSE, partes de plantilla y menús de navegación.','Recreate All Languages'=>'Recrear todos los idiomas','Recreate All Languages (Templates Only)'=>'Recrear todos los idiomas (solo plantillas)','Recreate All Languages (Template Parts Only)'=>'Recrear todos los idiomas (solo partes de plantilla)','Cancel'=>'Cancelar','Repair Template Metadata'=>'Reparar metadatos de plantilla','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Corrige el espacio de nombres del Editor del Sitio y la etiqueta _lf_lang en todas las plantillas FSE generadas por LF almacenadas en la base de datos. Ejecuta esto una vez después de actualizar desde una versión anterior de Lingua Forge — mueve las plantillas derivadas de WooCommerce del grupo de tema activo al grupo de WooCommerce en el Editor del Sitio, y asegura que todas las plantillas generadas sean detectables por los informes de cobertura.','Repair template metadata'=>'Reparar metadatos de plantilla','Request failed.'=>'La solicitud falló.','Forbidden'=>'Prohibido','Danger Zone'=>'Zona de peligro','Uninstall %s'=>'Desinstalar %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Elimina permanentemente todas las plantillas, partes de plantillas, patrones, menús de navegación, publicaciones, páginas, tipos de publicaciones personalizadas, productos y variaciones de productos asociados con este idioma. También elimina los archivos del paquete de idioma de WordPress para que este idioma ya no aparezca en el enrutador. Esta acción no se puede deshacer.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Este idioma coincide con la configuración regional de WordPress y no puede desinstalarse.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'¿Desea desinstalar permanentemente %s? Esto eliminará todo el contenido traducido para este idioma y no se puede deshacer.','Invalid language code.'=>'Código de idioma no válido.','This language is protected and cannot be uninstalled.'=>'Este idioma está protegido y no puede desinstalarse.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'La instalación de idiomas está deshabilitada en este servidor (DISALLOW_FILE_MODS está activado).','Invalid locale code.'=>'Código de idioma no válido.','Language %s installed successfully.'=>'El idioma %s se instaló correctamente.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'La instalación del paquete de idioma falló. El idioma puede ya estar instalado, el código de idioma puede ser incorrecto, o tu servidor puede bloquear las escrituras en archivos.','Navigations'=>'Navegaciones','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traducción de navegación requiere un proveedor de IA activo. Configura una clave API en la pestaña de Claves API.','Navigation'=>'Navegación','Re-translate'=>'Re-traducir','CPT Block Patterns'=>'Patrones de bloques CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patrones de bloques registrados para tipos de publicaciones personalizadas. Usa el botón de traducir para producir una variante en otro idioma. El contenido traducido se guarda aquí y puede copiarse en cualquier publicación CPT desde el inserter de patrones del editor de bloques o usarse como punto de partida para un patrón sincronizado (Bloque reutilizable).','Pattern'=>'Patrón','Post Types'=>'Tipos de publicaciones','✓ Translation saved'=>'✓ Traducción guardada','View'=>'Ver','Template Parts'=>'Partes de plantilla','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Copias específicas del idioma de las partes de plantilla del tema. Una vez estructuradas, las plantillas se actualizan para hacer referencia a la parte específica del idioma.','Re-create all'=>'Recrear todo','Translate all'=>'Traducir todo','Fix all links'=>'Arreglar todos los enlaces','Fix all navs'=>'Corregir todos los menús','Part'=>'Parte','Status / Actions'=>'Estado / Acciones','Create'=>'Crear','Templates'=>'Plantillas','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Plantillas FSE sembradas desde el tema activo. Crea y personaliza en el Editor del sitio.','Create missing'=>'Crear faltantes','Fix all parts'=>'Arreglar todas las partes','SEO'=>'SEO','Multilingual SEO'=>'SEO multilingüe','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Configurar hreflang, Open Graph, Schema.org, mapas del sitio y compartición social para cada idioma en su sitio. Cada sección a continuación maneja un aspecto del SEO multilingüe.','Open Graph &amp; Twitter Cards'=>'Tarjetas Open Graph y Twitter','Schema.org'=>'Schema.org','Sitemap'=>'Mapa del sitio','Analysis'=>'Análisis','Compatibility'=>'Compatibilidad','System'=>'Sistema','Overview'=>'Resumen','Lingua Forge Settings'=>'Configuraciones de Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge agrega enrutamiento multilingüe, traducción impulsada por IA, etiquetas hreflang SEO y un conmutador de idiomas a su sitio WordPress.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Utiliza las pestañas en la parte superior de esta página para configurar cada área. Los cambios en la pestaña del enrutador tienen efecto inmediato; los cambios en las claves de IA y configuraciones del modelo se aplican a la próxima solicitud de IA.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Después de cambiar la configuración de la estructura de URL (prefijo de ruta ↔ subdominio), visite siempre Configuración → Enlaces permanentes y haga clic en Guardar cambios para vaciar las reglas de reescritura.','AI Provider Tab'=>'Pestaña del proveedor de IA','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Proveedores soportados: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Selecciona el proveedor activo en el desplegable — solo se usa un proveedor a la vez. Ingresa una clave API para ese proveedor para habilitar funciones de IA.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Las claves están encriptadas en reposo usando AES-256-GCM con un secreto específico del sitio (LINGUAFORGE_SECRET). No compartas exportaciones de bases de datos sin rotar primero el secreto.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Las funciones de IA son opcionales. El enrutamiento de idiomas, hreflang, el conmutador de idiomas y el sistema de grupos de traducción funcionan sin un proveedor configurado.','Model tiers'=>'Niveles de modelo','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge usa dos niveles de modelos por proveedor:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Ligero: utilizado para descripciones meta y generación de extractos — rápido, de bajo costo.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Calidad: utilizado para la traducción de publicaciones y generación de contenido — mayor calidad, mayor costo.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Deje en blanco un campo de modelo para usar el predeterminado incorporado para ese nivel. El texto del marcador de posición muestra qué modelo se usará.','Translation Limits & Behavior'=>'Límites y comportamiento de la traducción','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Límites de traducción: controla qué roles de usuario pueden activar la traducción por IA y establece un presupuesto mensual de tokens. Superar el presupuesto suspende las llamadas a la IA hasta que se reinicie el mes.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportamiento: elija el preset de IA (Literal, Balanceado, Creativo), agregue instrucciones personalizadas en todo el sitio, habilite o deshabilite la traducción automática después de guardar la publicación y configure la Memoria de Traducción.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'La memoria de traducción almacena en caché los resultados de la IA por hash de contenido, par de idiomas, proveedor y modelo. La edición de una publicación invalida la entrada de la caché para que la próxima llamada de traducción obtenga un resultado nuevo.','Router Tab'=>'Pestaña de enrutador','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Idioma principal: el idioma en el que está escrito su contenido existente. Todas las traducciones se producen desde este idioma; cambiarlo no mueve ni elimina publicaciones.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Estructura de URL: modo prefijo de ruta (example.com/de/) no requiere cambios en el servidor. El modo subdominio (de.example.com) requiere un registro DNS comodín, un certificado SSL comodín y un cambio en la configuración del servidor web — consulta la guía de configuración del servidor.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Idiomas activos: agrega cada idioma que deseas soportar. Cada idioma obtiene un prefijo de URL o subdominio y una etiqueta hreflang en la cabecera &lt;head&gt; de la página.','WP site language requirement'=>'Requisito de idioma del sitio WP','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'El idioma del sitio de WordPress (Configuración → General → Idioma del sitio) debe estar configurado en uno de los idiomas que utilizas para el contenido, ya sea el idioma principal del contenido o uno de los idiomas secundarios. No puede ser un idioma que no tenga contenido en el sitio.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Ejemplo de configuración compatible: idioma del sitio WP = CA (Catalán), idiomas de contenido = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Ejemplo de configuración no compatible: idioma del sitio WP = EN (Inglés), idiomas de contenido = solo CA + ES. El inglés no es un idioma de contenido, por lo que Lingua Forge no puede mapear el locale de WP a ningún grupo de traducción.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Cuando el idioma del sitio WP no es un idioma de contenido: las consultas de productos de WooCommerce devuelven cero resultados en todos los bloques de catálogo; la delegación de imágenes de productos falla; todas las consultas de contenido filtrado por idioma se rompen; el selector de idioma puede mostrar una opción de idioma no relacionada con el contenido. Si ve una alerta de configuración en rojo en la parte superior de la pestaña Router o Sistema, corrija primero el idioma del sitio.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localización FSE: estructura, traduzca y corrija enlaces en plantillas y partes de plantillas de Edición Completa del Sitio directamente desde esta pestaña.','Glossary Tab'=>'Pestaña de Glosario','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Fije términos que no deben traducirse o que siempre deben mostrarse de una manera específica (por ejemplo, nombres de marcas, nombres de productos, acrónimos). Las restricciones del glosario se inyectan en cada solicitud de traducción de IA para todas las funciones: traducción de publicaciones, descripción meta, extracto y traducción de plantillas FSE.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Agregue un término por fila. Se requiere tanto el término fuente como la representación objetivo. El par de idiomas determina a qué trabajos de traducción se aplica la restricción.','SEO Tab'=>'Pestaña de SEO','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge es una solución completa de SEO multilingüe. No se requiere ningún plugin adicional de SEO o sitemap.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Lo que proporciona LF: etiquetas hreflang para cada idioma configurado, etiquetas Open Graph y Twitter Card con og:locale y og:locale:alternate, Schema.org JSON-LD con anotaciones inLanguage, y un sitemap multilingüe dedicado en /lf-sitemap.xml con entradas xhtml:link alternate para todos los grupos de traducción.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'El sitemap se anuncia automáticamente en robots.txt. Todos los principales motores de búsqueda — Google, Bing, Yandex — lo descubren desde robots.txt. No se requiere envío manual.','SEO plugins and conflict avoidance:'=>'Plugins de SEO y evitación de conflictos:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Si tienes instalado Yoast SEO, Rank Math, All in One SEO o SEOPress, Lingua Forge los detecta y se adapta para evitar salidas duplicadas. Para hreflang, LF toma el control por completo y suprime la salida del plugin porque esos plugins no pueden producir hreflang correcto para una configuración de enrutamiento multilingüe. Para Open Graph, LF solo añade og:locale y og:locale:alternate — las señales multilingües que el plugin no puede proporcionar — y deja el conjunto OG base al plugin. Para Schema.org, LF desactiva su propia salida por completo para evitar conflictos en los gráficos JSON-LD.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'La pestaña SEO → Compatibilidad muestra el estado de detección en vivo y explica exactamente qué hace LF en cada área de funciones.','SEO Scores'=>'Puntuaciones SEO','SEO Score System'=>'Sistema de puntuación SEO','Score computation'=>'Cálculo de puntuación','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Cada publicación se puntúa de 0 a 100 con seis métricas basadas en reglas: título, descripción meta, recuento de palabras, estructura de encabezados, cobertura de atributos de imágenes y enlaces internos. Siempre se otorgan diez puntos por tiempo de lectura (solo informativo). Los otros 90 puntos se distribuyen entre las otras métricas con pesos que varían según el perfil de contenido (ver abajo).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Cada métrica produce uno de cuatro estados: ok (peso completo), warn (50 % del peso), fail (0), o info (0, sin penalización). Una puntuación ≥ 80 es verde, 50–79 ámbar, por debajo de 50 rojo.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Reglas de puntuación de título (todos los perfiles): fallar si está vacío; advertir si tiene menos de 10 caracteres; advertir si solo tiene una palabra; advertir si es más largo que el límite SERP del perfil (60 caracteres para Blog, 70 para Producto/Landing); OK si tiene al menos 10 caracteres, al menos 2 palabras y está dentro del límite SERP.','Content profiles and weights'=>'Perfiles de contenido y pesos','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Los perfiles adaptan umbrales y pesos al tipo de contenido que se analiza. El perfil se resuelve automáticamente; puede sobrescribirlo por ejecución de análisis desde el menú desplegable de perfiles.','Blog / Editorial (default)'=>'Blog / Editorial (predeterminado)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Título 15 pts · Meta descripción 20 pts · Recuento de palabras 15 pts · Encabezados 20 pts · Imágenes 10 pts · Enlaces 10 pts. Límite de título en SERP 60 caracteres; meta 120–210 caracteres; advertencias de recuento de palabras por debajo de 300, fallos por debajo de 100; H2 requerido; enlaces internos requeridos.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Detectado automáticamente para productos WooCommerce. Título 20 pts · Meta descripción 30 pts · Recuento de palabras 15 pts · Encabezados 5 pts · Imágenes 20 pts · Enlaces 0 pts. Límite de SERP para el título 70 caracteres; advertencias de recuento de palabras por debajo de 80, fallos por debajo de 40; H2 y enlaces internos opcionales.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Detectado automáticamente para la página estática; puede seleccionarse manualmente. Título 20 pts · Meta descripción 30 pts · Recuento de palabras 15 pts · Encabezados 10 pts · Imágenes 15 pts · Enlaces 0 pts. Límite de SERP para el título 70 caracteres; advertencias de recuento de palabras por debajo de 150, fallos por debajo de 60; H2 y enlaces internos opcionales.','Heading structure rules'=>'Reglas de estructura de encabezados','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Se requiere exactamente un H1. El H1 normalmente es el título de la publicación renderizado por el tema — se lee de la página renderizada en vivo cuando es posible, y del contenido de la publicación como respaldo.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Cuando el perfil de Blog requiere un H2 y no se encuentra ninguno, el analizador primero verifica los subtítulos H3 antes de emitir una advertencia. Los bloques de acordeón y Detalles predeterminan H3 para sus encabezados; esos H3 se aceptan como estructura válida y producen un resultado correcto, no una advertencia.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'El contenido breve (3 párrafos o menos) nunca se penaliza por no tener subtítulos, independientemente del perfil. Una página concisa no se beneficia de una estructura de encabezados forzada.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Tratar H2 como equivalente a H1" (Configuración → SEO → Análisis): habilítalo cuando tu tema renderice el título de la publicación dentro de un H2 en lugar de un H1. El analizador promueve el primer H2 a H1 para que la puntuación no sea penalizada incorrectamente.','Score history and badges'=>'Historial de puntuaciones y medallas','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Cada vez que se analiza una publicación, la puntuación se almacena en los metadatos de la publicación. La columna de idioma en la lista de publicaciones muestra una insignia "SEO N" codificada por colores para cualquier publicación que haya sido analizada al menos una vez. Cuando se almacenan dos puntuaciones, un indicador de delta (↑N / ↓N) muestra el cambio desde la ejecución anterior.','AI Usage & Cache Tab'=>'Pestaña de uso de IA y caché','Token usage'=>'Uso de tokens','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'La tabla de uso muestra el consumo de tokens de IA desglosado por función (traducción, descripción meta, extracto, plantilla FSE, análisis por lotes), proveedor y modelo. Usa los botones de rango de fechas para filtrar por hoy, últimos 7 días, últimos 30 días o todo el tiempo.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'La cuota diaria (configurada en Comportamiento → Límites) se rastrea aquí. Cuando se alcanza la cuota, las llamadas a IA se suspenden por el resto del día. La tabla muestra cuánto de la cuota se ha consumido.','Translation caching'=>'Caché de traducción','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge usa dos capas de caché independientes para reducir llamadas redundantes a la API de IA:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Almacena respuestas en bruto de IA indexadas por hash de contenido, par de idiomas, proveedor, modelo y preajuste. Las entradas de caché se invalidan automáticamente cuando cambia el contenido de la publicación fuente. Limpia entradas individuales o toda la caché desde esta pestaña.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Almacena la salida completa traducida de la publicación por hash de contenido. Opt-in (habilitado en Comportamiento). Acelera traducciones repetidas de contenido sin cambios. Límpiala aquí cuando quieras forzar una pasada de IA fresca independientemente de si el contenido ha cambiado.','Maintenance Tab'=>'Pestaña de mantenimiento','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Sobrescrituras de idioma: gestione archivos de sobrescritura personalizados .po/.mo para las cadenas de la interfaz de usuario de Lingua Forge. Use esto en lugar de editar archivos del plugin directamente — las sobrescrituras sobreviven a las actualizaciones.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Depuración: habilite el registro de depuración para capturar los prompts de IA y las respuestas de API en un archivo local. Desactive después de solucionar problemas — el modo de depuración escribe un archivo en cada solicitud de IA.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Comportamiento de desinstalación: controla qué se elimina cuando se elimina el plugin desde Plugins → Plugins instalados → Eliminar. La configuración del plugin y las cachés de IA siempre se eliminan. Las asignaciones de idioma, relaciones de traducción, meta descripciones, glosario y Memoria de Traducción se mantienen por defecto para que una desinstalación o reinstalación accidental pueda continuar donde se quedó. Active "Eliminar datos de contenido al desinstalar" solo cuando elimine completamente el soporte multilingüe del sitio — esto no se puede deshacer.','System Tab'=>'Pestaña del sistema','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Diagnósticos de solo lectura para la instalación actual. No se cambian configuraciones aquí — úsalo para verificar la configuración, detectar problemas y recopilar información para informes de errores.','Sections'=>'Secciones','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Versiones de Lingua Forge, WordPress y PHP; tema activo; estructura de URL; idioma del sitio WP y idioma principal del contenido. Un indicador rojo junto al idioma del sitio WP significa que no es uno de los idiomas de contenido activos — corrígelo en Configuración → General antes de cualquier otra cosa.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Proveedor activo, claves configuradas, selecciones de nivel de modelo, preajuste y cuota diaria.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Confirma que la estructura de enlaces permanentes es compatible con el enrutamiento de rutas de Lingua Forge. Las estructuras simples y solo numéricas no son compatibles.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Lista cualquier plugin SEO de terceros activo. Lingua Forge adapta su salida cuando estos están presentes — consulta Configuración → SEO → Compatibilidad para el desglose por función.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'Versión de WooCommerce, modo de almacenamiento de pedidos (CPT / HPOS / compartido), y una tabla de cobertura de traducción por idioma para las cuatro páginas integradas de WC (Tienda, Carrito, Pago, Mi Cuenta).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Lista tipos de publicaciones que tienen publicaciones publicadas sin un valor meta _lf_lang. Las publicaciones que faltan esta etiqueta son invisibles para todos los filtros de idioma. Usa el botón Reparar para etiquetarlas con el idioma fuente, o Excluir para eliminar el tipo de publicación de la ruta de idioma por completo.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Volcado colapsable de todas las entradas propiedad de LF en $wp_rewrite->extra_rules_top. Útil para diagnosticar errores 404 o conflictos de enrutamiento después de agregar un nuevo idioma.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Resumen del sistema en texto plano de un clic que cubre todas las secciones anteriores. Pega esto en un problema de GitHub o solicitud de soporte para que el entorno completo sea visible de un vistazo.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'¿Encontraste un error o comportamiento inesperado? Por favor, abre un problema en GitHub — incluye el bloque de Información de Depuración arriba y una breve descripción de lo que esperabas vs. lo que sucedió.','Open an issue →'=>'Abrir un problema →','Getting started'=>'Comenzando','Server setup (subdomain)'=>'Configuración del servidor (subdominio)','Translation workflow'=>'Flujo de trabajo de traducción','Language switcher'=>'Conmutador de idiomas','WP-CLI reference'=>'Referencia de WP-CLI','Integration API'=>'API de integración','Documentation'=>'Documentación','Report an issue on GitHub'=>'Reportar un problema en GitHub','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'Cliente de IA de WordPress (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta Descripción, Generador de extractos','Translation, Content Generator'=>'Traducción, Generador de contenido','Testing…'=>'Probando…','✓ Connection OK'=>'✓ Conexión OK','✗ Failed:'=>'✗ Fallido:','No response from provider — check the error log for details.'=>'No hay respuesta del proveedor — revisa el registro de errores para más detalles.','Network error — could not reach the WordPress AJAX endpoint.'=>'Error de red — no se pudo acceder al endpoint AJAX de WordPress.','Translating a real post with this model…'=>'Traduciendo una publicación real con este modelo…','preset'=>'preset','Loading…'=>'Cargando…','Installing…'=>'Instalando…','✓ Language installed.'=>'✓ Idioma instalado.','✗ Error:'=>'✗ Error:','Creating…'=>'Creando…','✓ All templates created.'=>'✓ Todas las plantillas creadas.','Some templates could not be created.'=>'Algunas plantillas no pudieron ser creadas.','Recreating…'=>'Recreando…','✓ All templates recreated.'=>'✓ Todas las plantillas recreadas.','Some templates could not be recreated.'=>'Algunas plantillas no pudieron ser recreadas.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Esto sobrescribe esta plantilla con una copia nueva del tema activo, descartando cualquier personalización del Editor de sitios realizada en ella. Esto no se puede deshacer. ¿Continuar?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Esto sobrescribe cada plantilla con una copia nueva del tema activo, descartando cualquier personalización del Editor de sitios realizada en ellas. Esto no se puede deshacer. ¿Continuar?','✓ All parts recreated.'=>'✓ Todas las partes recreadas.','Some parts could not be recreated.'=>'Algunas partes no pudieron ser recreadas.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Esto sobrescribe esta parte de plantilla con una copia nueva del tema activo, descartando cualquier personalización del Editor de sitios realizada en ella. Esto no se puede deshacer. ¿Continuar?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Esto sobrescribe cada parte de plantilla con una copia nueva del tema activo, descartando cualquier personalización del Editor de sitios realizada en ellas. Esto no se puede deshacer. ¿Continuar?','✓ All parts created.'=>'✓ Todas las partes creadas.','Some parts could not be created.'=>'Algunas partes no pudieron ser creadas.','✓ All translated.'=>'✓ Todo traducido.','Some translations failed.'=>'Algunas traducciones fallaron.','Review carefully — links and slugs not updated.'=>'Revisa cuidadosamente — enlaces y slugs no actualizados.','Fixing…'=>'Arreglando…','✓ Links fixed.'=>'✓ Enlaces arreglados.','Some link fixes failed.'=>'Algunos arreglos de enlaces fallaron.','✓ Parts fixed.'=>'✓ Partes arregladas.','Some part fixes failed.'=>'Algunos arreglos de partes fallaron.','✓ Nav refs fixed.'=>'✓ Referencias de navegación arregladas.','Some nav ref fixes failed.'=>'Algunas referencias de navegación no pudieron ser arregladas.','✓ Pattern translated.'=>'✓ Patrón traducido.','Pattern translation failed.'=>'Fallo en la traducción del patrón.','Hide'=>'Ocultar','Re-create all templates'=>'Recrear todas las plantillas','Re-create all parts'=>'Recrear todas las partes','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Esto ejecuta Recrear todas las plantillas, Recrear todas las partes, Traducir todo, Corregir todas las partes y Corregir todos los enlaces para cada uno de tus {total} idiomas activos, uno a la vez. Sobrescribe las plantillas y partes existentes con copias nuevas del tema activo (descartando personalizaciones del Editor de sitios) y retraduce el contenido — nada de esto se puede deshacer. Traducir todo realiza llamadas reales a la API de IA para cada plantilla y parte, lo que puede llevar tiempo e incurrir en costos según tu proveedor. ¿Continuar?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Esto ejecuta Recrear todas las plantillas, Traducir todo, Corregir todas las partes y Corregir todos los enlaces para cada uno de tus {total} idiomas activos, uno a la vez — las partes de plantilla (encabezados, pies de página, etc.) se dejan sin tocar. Sobrescribe las plantillas existentes con copias nuevas del tema activo (descartando personalizaciones del Editor de sitios) y retraduce el contenido — nada de esto se puede deshacer. Traducir todo realiza llamadas reales a la API de IA para cada plantilla, lo que puede llevar tiempo e incurrir en costos según tu proveedor. ¿Continuar?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Esto ejecuta Recrear todas las partes (encabezados, pies de página y todas las demás partes de plantilla) para cada uno de tus {total} idiomas activos, uno a la vez. Sobrescribe las partes de plantilla existentes con copias nuevas del tema activo, descartando cualquier personalización del Editor de sitios realizada en ellas. Esto no se puede deshacer. ¿Continuar?','Starting…'=>'Iniciando…','Processing {lang} ({index} of {total}) — {step}…'=>'Procesando {lang} ({index} de {total}) — {step}…','Cancelled.'=>'Cancelado.','{done} of {total} languages processed.'=>'{done} de {total} idiomas procesados.','⚠ Done with issues.'=>'⚠ Completado con problemas.','✓ All {total} languages processed.'=>'✓ Se procesaron todos los {total} idiomas.','Built-in preset instructions:'=>'Instrucciones predefinidas incorporadas:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'No hay instrucciones predefinidas — cada función de IA usa sus propios valores predeterminados ajustados. Completa el campo de instrucciones de aviso personalizado a continuación para agregar tus propias reglas para todo el sitio.','Modified'=>'Modificado','edit'=>'editar','No published posts found for the selected filters.'=>'No se encontraron publicaciones publicadas con los filtros seleccionados.','Just now'=>'Justo ahora','Score'=>'Puntuación','Source title'=>'Título de origen','Multilingual SEO overview'=>'Resumen de SEO multilingüe','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Las puntuaciones son una señal, no un veredicto. Algunos contenidos están limitados estructuralmente — páginas muy cortas, páginas de destino con poco texto, o páginas cuyo propósito es la navegación en lugar de la información pueden puntuar más bajo por naturaleza. Usa esta visión general para detectar brechas genuinas de paridad entre idiomas, no para perseguir un número.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Esta es una página del sistema WooCommerce (Tienda, Carrito, Pago, etc.). Su contenido es gestionado por WooCommerce — la puntuación refleja solo señales estructurales, no contenido SEO editable por el usuario.','Settings'=>'Configuraciones','You do not have permission to manage these settings.'=>'No tienes permiso para gestionar estas configuraciones.','Lingua Forge — Settings'=>'Lingua Forge — Configuraciones','Settings saved.'=>'Configuraciones guardadas.','Save Settings'=>'Guardar configuraciones','Standard'=>'Estándar','Technical / Scientific'=>'Técnico / Científico','Legal / Compliance'=>'Legal / Cumplimiento','Creative / Marketing'=>'Creativo / Marketing','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — Estadísticas de Uso de IA','Lingua Forge AI Usage Statistics'=>'Estadísticas de Uso de Lingua Forge AI','Date'=>'Fecha','Request count'=>'Recuento de solicitudes','Full Article'=>'Artículo completo','Introduction only'=>'Solo introducción','Structured Outline'=>'Esquema estructurado','Generate Content'=>'Generar contenido','Hints'=>'Pistas','Key points, ideas, or structure to build from…'=>'Puntos clave, ideas o estructura sobre la que construir…','Tone'=>'Tono','Output'=>'Salida','Generate Excerpt'=>'Generar extracto','Generate Meta Description'=>'Generar meta descripción','Translate Content'=>'Traducir contenido','Mode'=>'Modo','Full post'=>'Publicación completa','Translate chunk'=>'Traducir fragmento','Target Language'=>'Idiom